// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../state.js";
import "../components/bell_resolver.js";
import { computeUnplacedCountsByClass } from "./unplaced_counts.js";
import { lessonMatchesFilter, hiddenCardCount, visibleCardCount } from "./view_filter.js";
import { buildStudentCardLookup, rowsFor as studentRowsFor } from "./student_view.js";
import { buildSupervisionLookup, rowsFor as supervisionRowsFor, supervisionChipHtml, supervisionSummary } from "./supervision_view.js";
import "./card_selection.js";

/**
 * Editor.render(rootEl) — writable timetable grid.
 * Rows = entities (class/teacher/room per APP.editor.perspective).
 * Cols = Monday-Saturday × the school's configured bell periods.
 * Pickup/place via Pointer Events (no HTML5 drag). See EDITOR.md (TBD).
 */
window.Editor = (function () {
  "use strict";

  const NUM_DAYS = 6; // hard maximum; the school's daysPerWeek drives the real count
  const DAY_LABELS_EN = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

  // Semantic zoom levels, coarsest first. The cycle order matches the row
  // heights, so stepping through it reads as zooming rather than reshuffling.
  const ZOOM_LEVELS = ["far", "mid", "near"];
  // "Standard", not "Codes": the legend button beside it is also called "Codes",
  // and two controls with one name read as one feature. This label names the
  // LEVEL (what a cell shows at the working zoom); the legend decodes codes.
  const ZOOM_LABELS = { far: "Compact", mid: "Standard", near: "Detail" };
  let pendingCardClickTimer = null;

  function cancelPendingCardClick() {
    if (pendingCardClickTimer !== null) {
      clearTimeout(pendingCardClickTimer);
      pendingCardClickTimer = null;
    }
  }

  // `density` was the old two-state control (compact | comfortable). It is kept
  // as a read-only alias so a returning user's saved preference and the rest of
  // the app keep working, and is translated once into a zoom level:
  // compact → mid (the same 36px working view), comfortable → near.
  function currentZoom() {
    const A = window.APP && window.APP.editor;
    if (!A) return "mid";
    if (ZOOM_LEVELS.indexOf(A.zoom) !== -1) return A.zoom;
    if (A.density === "comfortable") return "near";
    if (A.density === "compact") return "mid";
    return "mid";
  }

  function setZoom(level) {
    if (ZOOM_LEVELS.indexOf(level) === -1) return;
    const A = window.APP.editor;
    A.zoom = level;
    // Keep the legacy field in step for anything still reading it.
    A.density = level === "near" ? "comfortable" : "compact";
    try { localStorage.setItem("chronexa.editor.zoom", level); } catch (_e) {}
  }

  // The school decides how many weekdays to show (set in School settings at
  // setup). Clamp to the 6 we have labels for; default to a full week.
  function dayCount(S) {
    const n = S && (S.daysPerWeek | 0);
    return Math.max(1, Math.min(NUM_DAYS, n || NUM_DAYS));
  }

  /** Render into a host element. Re-render is safe (innerHTML replaced). */
  function render(rootEl) {
    if (!rootEl) return;
    ensureEditorState();
    const S = window.APP.school;
    if (!S) {
      rootEl.innerHTML = `<div class="chrx-editor-empty">Load a timetable to start editing.</div>`;
      return;
    }
    const perspective = window.APP.editor.perspective;
    const periods = displayPeriods(S);
    const visiblePeriodSet = new Set(periods.map(p => p.index | 0));
    const allRows = rowsFor(S, perspective);
    const focusRow = resolveFocusRow(allRows, perspective);
    const rows = window.APP.editor.viewMode === "focus" && focusRow ? [focusRow] : allRows;
    const mobileDay = window.APP.day || 0;

    // Per-render index: { rowKey -> { "d_p" -> card } }. Cheaper than scanning S.cards per cell.
    const cardLookup = buildCardLookup(S, perspective, visiblePeriodSet);

    rootEl.classList.add("chrx-editor");
    rootEl.classList.toggle("chrx-editor--focus", window.APP.editor.viewMode === "focus");
    rootEl.classList.toggle("chrx-readonly", perspective === "student" || perspective === "supervision");
    // Semantic zoom: the zoom level changes WHAT a cell shows, not just how big
    // it is. A denser grid is only useful if it still answers the question you
    // zoomed out to ask, so each step drops detail deliberately:
    //   far  — colour only, no text; for reading pattern and load at a glance
    //   mid  — the subject code; the aSc-style working view
    //   near — code + teacher + room; read a specific cell without hovering
    // Focus view has its own typography and ignores zoom.
    const zoomLevel = currentZoom();
    rootEl.classList.toggle("chrx-editor--zoom-far", window.APP.editor.viewMode !== "focus" && zoomLevel === "far");
    rootEl.classList.toggle("chrx-editor--zoom-mid", window.APP.editor.viewMode !== "focus" && zoomLevel === "mid");
    rootEl.classList.toggle("chrx-editor--zoom-near", window.APP.editor.viewMode !== "focus" && zoomLevel === "near");

    // Preserve scroll position across the innerHTML rebuild. Without this, a
    // pickup/place re-render reset the grid to the top — picking a card from a
    // bottom class (X) bounced the view back to class I/II (reported bug).
    const prevScroll = rootEl.querySelector(".chrx-grid-scroll");
    const savedTop = prevScroll ? prevScroll.scrollTop : 0;
    const savedLeft = prevScroll ? prevScroll.scrollLeft : 0;

    rootEl.innerHTML = window.APP.editor.viewMode === "focus" && focusRow
      ? focusHtml(S, allRows, focusRow, periods, cardLookup)
      : html(S, rows, periods, mobileDay, cardLookup);

    const newScroll = rootEl.querySelector(".chrx-grid-scroll");
    if (newScroll) { newScroll.scrollTop = savedTop; newScroll.scrollLeft = savedLeft; }

    fillOverviewStats(rootEl, S, rows, perspective);
    highlightToday(rootEl, S);
    enableLiftOnHover(rootEl);

    // Re-apply any pinch-zoom level to the freshly built grid (Plan C).
    if (window.APP.editor.gridZoom && window.APP.editor.gridZoom !== 1) {
      const g = rootEl.querySelector(".chrx-grid");
      if (g) g.style.setProperty("--chrx-grid-zoom", String(window.APP.editor.gridZoom));
    }

    wire(rootEl);
    syncCardInHandClass();
    autoFitRowLabels(rootEl);
    autoFitSubjectCodes(rootEl);
    syncUnplacedCount(S);
    updateClassPanel(S);
    applyDatedOverridesHook(rootEl, S);
    if (window.ConstraintExplainer && typeof window.ConstraintExplainer.attachTooltip === "function") {
      window.ConstraintExplainer.attachTooltip(rootEl);
    }
    initRovingTabindex(rootEl);
    syncSelectionUi(rootEl);
  }

  /* Hook for dated substitution overrides (Lane W2-4). */
  function applyDatedOverridesHook(rootEl, S) {
    if (window.Substitution && typeof window.Substitution.applyGridOverrides === "function") {
      window.Substitution.applyGridOverrides(rootEl, S);
    }
  }

  function buildCardLookup(S, perspective, visiblePeriodSet) {
    const filter = currentViewFilter();
    if (perspective === "student") {
      return buildStudentCardLookup(S, visiblePeriodSet, dayCount(S), filter);
    }
    if (perspective === "supervision") {
      return buildSupervisionLookup(S, visiblePeriodSet, dayCount(S));
    }
    const lookup = Object.create(null);
    for (const c of (S.cards || [])) {
      const day = parseInt(c.day, 10);
      const period = parseInt(c.period, 10);
      if (!Number.isFinite(day) || day < 0 || day >= dayCount(S)) continue;
      if (!visiblePeriodSet.has(period | 0)) continue;
      const lesson = S._idx.lessonById[c.lessonId];
      if (!lesson) continue;
      // Week/term view filter (lane W3b-7): a card whose lesson does not run in
      // the selected week/term is not drawn at all — see js/ui/editor/view_filter.js.
      if (!lessonMatchesFilter(lesson, filter, S)) continue;
      const key = day + "_" + period;
      const keysForCard = rowKeysForCard(lesson, perspective, c);
      for (const rowKey of keysForCard) {
        if (!lookup[rowKey]) lookup[rowKey] = Object.create(null);
        if (!lookup[rowKey][key]) lookup[rowKey][key] = [];
        lookup[rowKey][key].push(c);
      }
    }
    return lookup;
  }

  /** The editor's live week/term view filter (lane W3b-7); "all" when unset. */
  function currentViewFilter() {
    return window.ViewFilter && typeof window.ViewFilter.currentFilter === "function"
      ? window.ViewFilter.currentFilter()
      : { week: "all", term: "all" };
  }

  function rowKeysForCard(lesson, perspective, card) {
    if (perspective === "class") return lesson.classIds;
    if (perspective === "teacher") return lesson.teacherIds;
    if (perspective === "subject") return lesson.subjectId ? [lesson.subjectId] : [];
    if (perspective === "room") {
      const rid = card.classroomId || lesson.preferredRoomId;
      return rid ? [rid] : [];
    }
    return [];
  }

  /** Switch perspective and re-render. */
  function setPerspective(p, hostEl) {
    ensureEditorState();
    window.APP.editor.perspective = p;
    render(hostEl);
  }

  function ensureEditorState() {
    const A = window.APP;
    A.editor = A.editor || {};
    if (!A.editor.perspective) A.editor.perspective = "class";
    if (!A.editor.colorBy) A.editor.colorBy = "subject";
    if (!A.editor.viewMode) A.editor.viewMode = "focus";
    if (!A.editor.focusRowByPerspective) A.editor.focusRowByPerspective = {};
    if (A.editor.cardInHand === undefined) A.editor.cardInHand = null;
    if (!Array.isArray(A.editor.selectedCardIds)) A.editor.selectedCardIds = [];
    if (A.editor.selectionAnchorCardId === undefined) A.editor.selectionAnchorCardId = null;
    if (!A.editor.cardClipboard) A.editor.cardClipboard = null;
    if (!A.editor.weekFilter) A.editor.weekFilter = "all";
    if (!A.editor.termFilter) A.editor.termFilter = "all";
  }

  function selectionBarHtml() {
    return `
      <div class="chrx-selection-bar" data-selection-bar hidden role="toolbar" aria-label="Selected card actions">
        <span class="chrx-selection-bar__count" data-selection-count>0 selected</span>
        <div class="chrx-selection-bar__actions">
          <button type="button" data-selection-action="lock">Lock</button>
          <button type="button" data-selection-action="unlock">Unlock</button>
          <button type="button" data-selection-action="unplace">Unplace</button>
          <button type="button" data-selection-action="delete">Delete</button>
          <button type="button" data-selection-action="move-day" data-selection-delta="-1" aria-label="Move selected cards one day earlier">← day</button>
          <button type="button" data-selection-action="move-day" data-selection-delta="1" aria-label="Move selected cards one day later">day →</button>
          <button type="button" data-selection-action="clear">Clear</button>
        </div>
      </div>
    `;
  }

  function selectionRecords(S) {
    const ids = new Set(window.APP?.editor?.selectedCardIds || []);
    return (S?.cards || []).filter(card => ids.has(CardSelection.cardKey(card)));
  }

  function selectedCardsWithBlocks(S) {
    const out = [];
    const seen = new Set();
    for (const card of selectionRecords(S)) {
      const length = CardSelection.cardLength(S, card);
      let startPeriod = Number(card.period);
      for (let offset = 1; offset < length; offset++) {
        const previous = (S.cards || []).find(candidate =>
          candidate.lessonId === card.lessonId &&
          Number(candidate.day) === Number(card.day) &&
          Number(candidate.period) === startPeriod - 1);
        if (!previous) break;
        startPeriod = Number(previous.period);
      }
      for (let offset = 0; offset < length; offset++) {
        const item = (S.cards || []).find(candidate =>
          candidate.lessonId === card.lessonId &&
          Number(candidate.day) === Number(card.day) &&
          Number(candidate.period) === startPeriod + offset);
        if (!item) continue;
        const key = CardSelection.cardKey(item);
        if (!seen.has(key)) {
          seen.add(key);
          out.push(item);
        }
      }
      // A malformed/imported double card can have only its first model card;
      // retain that card so bulk lock/delete still does what the user asked.
      if (!seen.has(CardSelection.cardKey(card))) {
        seen.add(CardSelection.cardKey(card));
        out.push(card);
      }
    }
    return out;
  }

  function editorHost() {
    return document.querySelector(".chrx-editor");
  }

  function rerenderEditorAndPending() {
    const host = editorHost();
    if (host) render(host);
    const pending = document.querySelector(".chrx-pending-strip");
    if (pending && window.PendingStrip?.render) window.PendingStrip.render(pending);
  }

  function notifySelection(message, level) {
    if (typeof window._chrxNotify === "function") window._chrxNotify(message, level);
    else if (message) console.info("[selection]", message);
  }

  function cardMatchesRow(S, card, rowKey, perspective) {
    const lesson = S?._idx?.lessonById?.[card?.lessonId] ||
      (S?.lessons || []).find(item => item.id === card?.lessonId);
    if (!lesson || !rowKey) return false;
    if (perspective === "class") return (lesson.classIds || []).includes(rowKey);
    if (perspective === "teacher") return (lesson.teacherIds || []).includes(rowKey);
    if (perspective === "subject") return lesson.subjectId === rowKey;
    if (perspective === "room") return (card.classroomId || lesson.preferredRoomId) === rowKey;
    return false;
  }

  function pasteOccupiedKeys(S, anchor) {
    const perspective = window.APP?.editor?.perspective || "class";
    const occupied = new Set();
    for (const card of (S?.cards || [])) {
      if (cardMatchesRow(S, card, anchor?.rowKey, perspective)) {
        occupied.add(CardSelection.slotKey(card.day, card.period));
      }
    }
    return occupied;
  }

  function bulkMoveByDay(delta) {
    if (isReadOnlyPerspective()) return;
    const S = window.APP && window.APP.school;
    if (!S) return;
    const selected = selectedCardsWithBlocks(S);
    if (!selected.length) return;
    // A double-period lesson has one model card per period. Plan once from
    // the first period, then move the whole contiguous block together.
    const selectedRoots = selected.filter(card => {
      const length = CardSelection.cardLength(S, card);
      return length === 1 || !selected.some(previous =>
        previous.lessonId === card.lessonId &&
        Number(previous.day) === Number(card.day) &&
        Number(previous.period) === Number(card.period) - 1);
    });
    const selectedSet = new Set(selected);
    const days = Math.max(1, Math.min(NUM_DAYS, Number(S.daysPerWeek) || NUM_DAYS));
    const existing = (S.cards || []).filter(card => !selectedSet.has(card));
    const planned = [];
    const claimed = new Set();
    const skipped = [];
    const slotKey = (day, period) => `${day}|${period}`;
    const periods = new Set((S.bell?.periods || [])
      .map(period => Number(period?.index)).filter(Number.isFinite));
    const hasPeriodList = periods.size > 0;

    for (const card of selectedRoots) {
      const day = Number(card.day) + Number(delta);
      const period = Number(card.period);
      const lesson = S._idx?.lessonById?.[card.lessonId] ||
        (S.lessons || []).find(item => item.id === card.lessonId);
      const length = CardSelection.cardLength(S, card);
      if (card.locked || lesson?.fixedDay != null || lesson?.fixedPeriod != null) {
        skipped.push({ card, reason: "locked" });
        continue;
      }
      if (day < 0 || day >= days) {
        skipped.push({ card, reason: "outside-grid" });
        continue;
      }
      const targetSlots = Array.from({ length }, (_, offset) => slotKey(day, period + offset));
      if (hasPeriodList && targetSlots.some(key => !periods.has(Number(key.split("|")[1])))) {
        skipped.push({ card, reason: "outside-grid" });
        continue;
      }
      if (targetSlots.some(key => claimed.has(`${card.lessonId}|${key}`) || existing.some(item =>
        item.lessonId === card.lessonId && slotKey(Number(item.day), Number(item.period)) === key))) {
        skipped.push({ card, reason: "occupied" });
        continue;
      }
      let validity = "green";
      if (window.Placement?.classify && lesson) {
        for (let offset = 0; offset < length; offset++) {
          const targetPeriod = period + offset;
          const plannedCards = planned.flatMap(move => Array.from(
            { length: CardSelection.cardLength(S, move.card) },
            (_, plannedOffset) => ({
              lessonId: move.card.lessonId,
              day: move.day,
              period: Number(move.period) + plannedOffset,
              classroomId: move.card.classroomId,
            }),
          ));
          const prefiltered = existing.filter(item =>
            Number(item.day) === day && Number(item.period) === targetPeriod)
            .concat(plannedCards.filter(item =>
              Number(item.day) === day && Number(item.period) === targetPeriod));
          const result = window.Placement.classify(
            card.lessonId, day, targetPeriod,
            card.classroomId || lesson.preferredRoomId,
            prefiltered,
          );
          if (result && result.validity === "red") {
            validity = "red";
            break;
          }
        }
      }
      if (validity === "red") {
        skipped.push({ card, reason: "conflict" });
        continue;
      }
      targetSlots.forEach(key => claimed.add(`${card.lessonId}|${key}`));
      planned.push({ card, day, period });
    }

    if (planned.length) {
      window.APP.mutate("Move selected cards by day", () => {
        for (const move of planned) {
          const length = CardSelection.cardLength(S, move.card);
          for (const item of selected) {
            if (item.lessonId !== move.card.lessonId ||
                Number(item.day) !== Number(move.card.day) ||
                Number(item.period) < Number(move.card.period) ||
                Number(item.period) >= Number(move.card.period) + length) continue;
            item.day = move.day;
          }
        }
      });
      // Card ids are positional in the current renderer. Keep the selection
      // attached to the moved objects instead of leaving stale ids behind.
      window.APP.editor.selectedCardIds = selected.map(CardSelection.cardKey);
      window.APP.editor.selectionAnchorCardId = window.APP.editor.selectedCardIds[0] || null;
      rerenderEditorAndPending();
    }
    const moved = planned.length;
    const suffix = skipped.length ? `; ${skipped.length} skipped` : "";
    notifySelection(`Moved ${moved} card${moved === 1 ? "" : "s"} by ${delta > 0 ? "one day later" : "one day earlier"}${suffix}.`);
  }

  function bulkSelectionAction(action) {
    if (isReadOnlyPerspective()) return;
    const S = window.APP && window.APP.school;
    if (!S) return;
    const selected = selectedCardsWithBlocks(S);
    if (!selected.length) return;
    if (action === "clear") return clearSelection(editorHost());
    if (action === "move-day") return bulkMoveByDay(Number(arguments[1]) || 0);

    const selectedSet = new Set(selected);
    const label = action === "lock" ? "Lock selected cards"
      : action === "unlock" ? "Unlock selected cards"
      : action === "delete" ? "Delete selected cards"
      : "Unplace selected cards";
    window.APP.mutate(label, () => {
      if (action === "lock") {
        selected.forEach(card => { card.locked = true; });
      } else if (action === "unlock") {
        selected.forEach(card => { delete card.locked; });
      } else {
        S.cards = (S.cards || []).filter(card => !selectedSet.has(card));
      }
    });

    const removed = action === "lock" || action === "unlock" ? 0 : selected.length;
    if (removed) {
      document.dispatchEvent(new CustomEvent("editor:unplace", {
        detail: { cardIds: selected.map(CardSelection.cardKey), bulk: true },
      }));
      window.APP.editor.selectedCardIds = [];
      window.APP.editor.selectionAnchorCardId = null;
      rerenderEditorAndPending();
    } else {
      rerenderEditorAndPending();
    }
    notifySelection(`${label.replace(" selected cards", "")} ${selected.length} card${selected.length === 1 ? "" : "s"}.`);
  }

  function copySelection() {
    const S = window.APP && window.APP.school;
    const copied = CardSelection.clipboardForCards(S, selectionRecords(S));
    if (!copied) return false;
    window.APP.editor.cardClipboard = copied;
    notifySelection(`Copied ${copied.cards.length} card${copied.cards.length === 1 ? "" : "s"}.`);
    return true;
  }

  function pasteAnchorFromUi() {
    const stored = window.APP?.editor?.pasteAnchor;
    if (stored && Number.isFinite(Number(stored.day)) && Number.isFinite(Number(stored.period))) return stored;
    const active = document.activeElement?.closest?.(".chrx-slot");
    if (active) return {
      day: Number(active.dataset.day), period: Number(active.dataset.period),
      rowKey: active.dataset.row || "",
    };
    return null;
  }

  function pasteSelection() {
    if (isReadOnlyPerspective()) return;
    const S = window.APP && window.APP.school;
    const clipboard = window.APP?.editor?.cardClipboard;
    const anchor = pasteAnchorFromUi();
    if (!S || !clipboard || !anchor) {
      notifySelection("Hover or focus a timetable slot before pasting.", "warn");
      return false;
    }
    const reservedSlots = new Set();
    const plan = CardSelection.planPaste(S, clipboard.cards, anchor, pasteOccupiedKeys(S, anchor), {
      canPlace: ({ lesson, day, period, length }) => {
        const perspective = window.APP.editor.perspective || "class";
        const rowIds = perspective === "class" ? lesson.classIds
          : perspective === "teacher" ? lesson.teacherIds
          : perspective === "subject" ? [lesson.subjectId]
          : null;
        if (rowIds && anchor.rowKey && !rowIds.includes(anchor.rowKey)) return false;
        const targets = Array.from({ length }, (_, offset) => `${day}|${period + offset}`);
        if (targets.some(key => reservedSlots.has(key))) return false;
        if (window.Placement?.classify) {
          const existing = (S.cards || []).filter(card =>
            Number(card.day) === day && Number(card.period) >= period &&
            Number(card.period) < period + length);
          for (let offset = 0; offset < length; offset++) {
            const result = window.Placement.classify(
              lesson.id, day, period + offset,
              anchor.rowKey && window.APP.editor.perspective === "room" ? anchor.rowKey : lesson.preferredRoomId,
              existing.filter(card => Number(card.period) === period + offset),
            );
            if (result && result.validity === "red") return false;
          }
        }
        targets.forEach(key => reservedSlots.add(key));
        return true;
      },
    });
    if (!plan.cards.length) {
      notifySelection("Nothing could be pasted: the selected lessons have no weekly count available or the target is occupied.", "warn");
      return false;
    }

    if (window.APP.editor.perspective === "room" && anchor.rowKey) {
      plan.cards.forEach(card => { card.classroomId = anchor.rowKey; });
    }
    window.APP.mutate("Paste cards", () => {
      S.cards.push(...plan.cards.map(card => ({ ...card })));
    });
    window.APP.editor.selectedCardIds = plan.cards.map(CardSelection.cardKey);
    window.APP.editor.selectionAnchorCardId = window.APP.editor.selectedCardIds[0] || null;
    rerenderEditorAndPending();
    const skipped = plan.skipped.length;
    notifySelection(`Pasted ${plan.cards.length} card${plan.cards.length === 1 ? "" : "s"}${skipped ? `; ${skipped} skipped` : ""}.`);
    return true;
  }

  function syncSelectionUi(rootEl) {
    if (!rootEl) return;
    ensureEditorState();
    const S = window.APP && window.APP.school;
    const liveIds = new Set((S?.cards || []).map(CardSelection.cardKey));
    window.APP.editor.selectedCardIds = isReadOnlyPerspective() ? [] : window.APP.editor.selectedCardIds
      .filter(id => liveIds.has(id));

    const selected = new Set(window.APP.editor.selectedCardIds);
    rootEl.querySelectorAll(".chrx-vkarta").forEach(card => {
      const isSelected = selected.has(card.dataset.cardId);
      card.classList.toggle("chrx-vkarta--selected", isSelected);
      card.setAttribute("aria-selected", isSelected ? "true" : "false");
    });
    const bar = rootEl.querySelector("[data-selection-bar]");
    if (!bar) return;
    const count = selected.size;
    bar.hidden = count < 2;
    const countEl = bar.querySelector("[data-selection-count]");
    if (countEl) countEl.textContent = `${count} selected`;
  }

  function selectedCardElementMeta(rootEl) {
    return Array.from(rootEl.querySelectorAll(".chrx-vkarta")).map(card => {
      const slot = card.closest(".chrx-slot");
      return {
        id: card.dataset.cardId,
        rowKey: slot?.dataset.row || card.closest(".chrx-row")?.dataset.row || "",
        day: Number(card.dataset.day),
        period: Number(card.dataset.period),
      };
    });
  }

  // Student and Supervision perspectives are read-only views: no selection, bulk action or paste
  // may change the timetable from them.
  function isReadOnlyPerspective() {
    const persp = window.APP && window.APP.editor && window.APP.editor.perspective;
    return persp === "student" || persp === "supervision";
  }

  function selectCardElement(card, options = {}) {
    if (isReadOnlyPerspective()) return;
    const rootEl = card && card.closest(".chrx-editor");
    if (!rootEl || !card.dataset.cardId) return;
    ensureEditorState();
    const metas = selectedCardElementMeta(rootEl);
    const id = card.dataset.cardId;
    const anchorId = window.APP.editor.selectionAnchorCardId;
    if (options.range && anchorId) {
      window.APP.editor.selectedCardIds = CardSelection.range(metas, anchorId, id);
    } else if (options.toggle) {
      window.APP.editor.selectedCardIds = CardSelection.toggle(window.APP.editor.selectedCardIds, id);
    } else if (options.extend) {
      window.APP.editor.selectedCardIds = CardSelection.toggle(window.APP.editor.selectedCardIds, id);
      if (!window.APP.editor.selectedCardIds.includes(id)) {
        window.APP.editor.selectedCardIds.push(id);
      }
    } else {
      window.APP.editor.selectedCardIds = [id];
    }
    if (!options.preserveAnchor) window.APP.editor.selectionAnchorCardId = id;
    syncSelectionUi(rootEl);
  }

  function clearSelection(rootEl) {
    ensureEditorState();
    window.APP.editor.selectedCardIds = [];
    window.APP.editor.selectionAnchorCardId = null;
    syncSelectionUi(rootEl || document.querySelector(".chrx-editor"));
  }

  function onSelectionShortcut(ev) {
    const key = String(ev.key || "").toLowerCase();
    const modified = ev.metaKey || ev.ctrlKey;
    const target = ev.target;
    const tag = String(target?.tagName || "").toLowerCase();
    const typing = tag === "input" || tag === "textarea" || tag === "select" || target?.isContentEditable;
    if (typing || !window.APP?.editor || window.APP.editor.cardInHand) return;
    const rootEl = document.querySelector(".chrx-editor");
    if (!rootEl || !window.APP.school) return;
    if (modified && !ev.altKey && key === "c" && window.APP.editor.selectedCardIds?.length) {
      ev.preventDefault();
      ev.stopPropagation();
      copySelection();
      return;
    }
    if (modified && !ev.altKey && key === "v" && window.APP.editor.cardClipboard) {
      ev.preventDefault();
      ev.stopPropagation();
      pasteSelection();
      return;
    }
    if (key === "escape" && window.APP.editor.selectedCardIds?.length &&
        (rootEl.contains(document.activeElement) || rootEl.contains(target))) {
      ev.preventDefault();
      ev.stopPropagation();
      clearSelection(rootEl);
    }
  }

  function setPasteAnchor(slot) {
    if (!slot || slot.classList.contains("out-of-bell")) return;
    ensureEditorState();
    const day = Number(slot.dataset.day);
    const period = Number(slot.dataset.period);
    if (!Number.isFinite(day) || !Number.isFinite(period)) return;
    window.APP.editor.pasteAnchor = {
      day,
      period,
      rowKey: slot.dataset.row || "",
    };
  }

  function marqueeSelection(rootEl, startEvent, startSlot) {
    if (isReadOnlyPerspective()) return;
    if (!rootEl || !startSlot || startSlot.classList.contains("out-of-bell")) return;
    const pointerId = startEvent.pointerId;
    const startX = startEvent.clientX;
    const startY = startEvent.clientY;
    const owner = rootEl;
    const additive = !!(startEvent.metaKey || startEvent.ctrlKey || startEvent.shiftKey);
    const base = additive ? new Set(window.APP.editor.selectedCardIds || []) : new Set();
    let moved = false;
    let marquee = null;

    function ensureMarquee() {
      if (marquee) return;
      marquee = document.createElement("div");
      marquee.className = "chrx-selection-marquee";
      marquee.setAttribute("aria-hidden", "true");
      document.body.appendChild(marquee);
    }

    function paint(x, y) {
      if (!moved && Math.hypot(x - startX, y - startY) < 5) return;
      moved = true;
      ensureMarquee();
      const left = Math.min(startX, x);
      const top = Math.min(startY, y);
      marquee.style.left = `${left}px`;
      marquee.style.top = `${top}px`;
      marquee.style.width = `${Math.abs(x - startX)}px`;
      marquee.style.height = `${Math.abs(y - startY)}px`;
    }

    function finish(x, y) {
      const left = Math.min(startX, x);
      const right = Math.max(startX, x);
      const top = Math.min(startY, y);
      const bottom = Math.max(startY, y);
      const ids = new Set(base);
      if (moved) {
        rootEl.querySelectorAll(".chrx-vkarta").forEach(card => {
          const rect = card.getBoundingClientRect();
          const intersects = rect.right >= left && rect.left <= right &&
            rect.bottom >= top && rect.top <= bottom;
          if (intersects && card.dataset.cardId) ids.add(card.dataset.cardId);
        });
        window.APP.editor.selectedCardIds = Array.from(ids);
        const last = Array.from(ids).pop() || null;
        if (last) window.APP.editor.selectionAnchorCardId = last;
        syncSelectionUi(rootEl);
      }
    }

    function move(ev) {
      if (ev.pointerId !== pointerId) return;
      paint(ev.clientX, ev.clientY);
      if (moved) ev.preventDefault();
    }

    function up(ev) {
      if (ev.pointerId !== pointerId) return;
      finish(ev.clientX, ev.clientY);
      if (marquee && marquee.parentNode) marquee.parentNode.removeChild(marquee);
      owner.releasePointerCapture?.(pointerId);
      document.removeEventListener("pointermove", move, true);
      document.removeEventListener("pointerup", up, true);
      document.removeEventListener("pointercancel", up, true);
    }

    owner.setPointerCapture?.(pointerId);
    document.addEventListener("pointermove", move, true);
    document.addEventListener("pointerup", up, true);
    document.addEventListener("pointercancel", up, true);
  }

  function resolveFocusRow(rows, perspective) {
    if (!rows.length) return null;
    const stored = window.APP.editor.focusRowByPerspective[perspective];
    const row = rows.find(item => item.key === stored) || rows[0];
    window.APP.editor.focusRowByPerspective[perspective] = row.key;
    return row;
  }

  function displayPeriods(S) {
    const raw = (S && S.bell && Array.isArray(S.bell.periods)) ? S.bell.periods : [];
    const byIndex = Object.create(null);
    for (const p of raw) {
      const ix = p && Number.isFinite(p.index) ? p.index : parseInt(p && p.index, 10);
      if (!Number.isFinite(ix) || ix <= 0) continue;
      byIndex[ix] = {
        ...p,
        index: ix,
        label: p.label || ("P" + ix),
        synthetic: false,
      };
    }
    const out = Object.keys(byIndex)
      .map(k => byIndex[k])
      .sort((a, b) => (a.index | 0) - (b.index | 0));
    if (out.length) return out;

    const fallbackCount = Math.max(1, Math.min(30, (S && S.periodsPerDay | 0) || 8));
    return Array.from({ length: fallbackCount }, (_, i) => ({
      index: i + 1,
      label: "P" + (i + 1),
      isTeaching: false,
      synthetic: true,
    }));
  }

  function syncCardInHandClass() {
    document.body.classList.toggle(
      "chrx-card-in-hand",
      !!window.APP.editor.cardInHand
    );
  }

  function rowsFor(S, perspective) {
    if (perspective === "teacher") {
      return S.teachers.map(t => ({
        key: t.id,
        label: t.name,
        sub: t.abbr || "",
      }));
    }
    if (perspective === "room") {
      return S.classrooms.map(r => ({ key: r.id, label: r.name, sub: "" }));
    }
    if (perspective === "subject") {
      return (S.subjects || []).map(s => ({
        key: s.id,
        label: s.name,
        sub: s.abbr && s.abbr !== s.name ? s.abbr : "",
      }));
    }
    if (perspective === "student") {
      return studentRowsFor(S);
    }
    if (perspective === "supervision") {
      return supervisionRowsFor(S);
    }
    // default = class
    return S.classes.map(c => ({ key: c.id, label: c.name, sub: "" }));
  }

  function html(S, rows, periods, mobileDay, cardLookup) {
    const numDays = dayCount(S);
    const headerHtml = headerRowHtml(periods, mobileDay, numDays);
    const dayTabsHtml = dayTabsHtml_(mobileDay, numDays);

    const bodyHtml = rows.length
      ? rows.map(row => rowHtml(S, row, periods, mobileDay, cardLookup, numDays)).join("")
      : emptyRowsHtml();

    // The in-grid tools row was removed — it duplicated the step-6 header
    // buttons (perspective/color/density, wired in main.js) and cost the
    // grid a full row of height. The live unplaced count syncs into the
    // header's #editor-unplaced-count span instead (see render()).
    return `
      <div class="chrx-overview-bar">
        <div class="chrx-ob-lockup">
          <span class="chrx-ob-title">${esc(overviewTitle())}</span>
          <span class="chrx-ob-sub">${rows.length} ${esc(PERSPECTIVE_PLURAL[window.APP.editor.perspective || "class"] || "rows")} · ${periods.length || 8} periods</span>
        </div>
        <div class="chrx-ob-stats" id="chrx-ob-stats" aria-live="polite"></div>
        <button type="button" data-focus-nav="focus">Focus board</button>
      </div>
      ${selectionBarHtml()}
      ${dayTabsHtml}
      <div class="chrx-grid-scroll">
        <div class="chrx-grid" style="--chrx-periods:${periods.length || 8}">
          ${headerHtml}
          ${bodyHtml}
        </div>
      </div>
    `;
  }

  /* The supervision plan can legitimately be empty — the bundled demo ships no
     supervision rows at all — so say so, and offer the one next step that
     exists, rather than showing an empty grid. */
  function emptyRowsHtml() {
    if ((window.APP.editor.perspective || "class") !== "supervision") return "";
    return `
      <div class="chrx-sup-empty" role="row" style="grid-column:1/-1;padding:30px 20px;text-align:center;color:var(--chrx-fg-tertiary,#64748b);font:400 13px/1.5 var(--chrx-font-sans);">
        <p style="margin:0 0 8px;font-weight:700;font-size:15px;color:var(--chrx-fg,#0f172a);">No supervision slots yet</p>
        <p style="margin:0 0 14px;">Nothing is being supervised. Add who is on duty in which hall, day and period.</p>
        <button type="button" data-editor-tool="open-supervisions" style="border:1px solid var(--chrx-line,#e2e8f0);background:var(--chrx-bg-tile,#fff);border-radius:8px;padding:8px 14px;font:600 12px var(--chrx-font-sans);cursor:pointer;">Add supervision slots…</button>
      </div>`;
  }

  function overviewTitle() {
    const school = window.APP.school;
    const name = school && school.schoolName;
    return name ? name : "Untitled timetable";
  }

  function isMobileViewport(rootEl) {
    if (typeof window === "undefined") return false;
    if (typeof window.matchMedia === "function") {
      const mq = window.matchMedia("(max-width: 767px)");
      if (mq && mq.matches) return true;
    }
    const docEl = typeof document !== "undefined" && document.documentElement;
    const clientW = docEl && docEl.clientWidth;
    if (clientW && clientW > 0 && clientW <= 767) return true;
    const innerW = window.innerWidth;
    if (innerW && innerW > 0 && innerW <= 767) return true;
    const board = (rootEl && rootEl.querySelector && rootEl.querySelector(".chrx-focus-board, .chrx-focus-workspace")) ||
                  (typeof document !== "undefined" && document.querySelector(".chrx-focus-board, .chrx-focus-workspace"));
    if (board && board.clientWidth > 0 && board.clientWidth <= 767) return true;
    return false;
  }

  function focusHtml(S, allRows, focusRow, periods, cardLookup) {
    const numDays = dayCount(S);
    const mobileDay = Math.max(0, Math.min(numDays - 1, (window.APP && window.APP.day) || 0));
    const isMobile = isMobileViewport();
    const dayTabsHtml = dayTabsHtml_(mobileDay, numDays);
    const perspective = window.APP.editor.perspective || "class";
    const options = allRows.map(row =>
      `<option value="${esc(row.key)}"${row.key === focusRow.key ? " selected" : ""}>${esc(row.label)}</option>`
    ).join("");

    let classRailHtml = "";
    if (perspective === "class") {
      const focusFilter = currentViewFilter();
      const unplacedCounts = computeUnplacedCountsByClass(S, {
        lessonFilter: (L) => lessonMatchesFilter(L, focusFilter, S),
      });
      const railItems = allRows.map(row => {
        const isSelected = row.key === focusRow.key;
        const count = unplacedCounts[row.key] || 0;
        // Show no badge for zero; show plain numeric count beside class when >0 (VI A  1).
        const countHtml = count > 0
          ? ` <span class="chrx-class-rail__count" data-count="${count}">${count}</span>`
          : "";
        return `<button type="button" class="chrx-class-rail__item${isSelected ? " is-active" : ""}" data-class-id="${esc(row.key)}" data-unplaced-count="${count}" aria-selected="${isSelected ? "true" : "false"}" title="${esc(row.label)}${count > 0 ? ` (${count} unplaced)` : ""}">
          <span class="chrx-class-rail__label">${esc(row.label)}</span>${countHtml}
        </button>`;
      }).join("");

      classRailHtml = `
        <nav class="chrx-class-rail" aria-label="Class timetable list">
          <div class="chrx-class-rail__list" role="tablist" aria-orientation="vertical">
            ${railItems}
          </div>
        </nav>
      `;
    } else if (perspective === "student") {
      const railItems = allRows.map(row => {
        const isSelected = row.key === focusRow.key;
        return `<button type="button" class="chrx-class-rail__item chrx-student-rail__item${isSelected ? " is-active" : ""}" data-class-id="${esc(row.key)}" data-student-id="${esc(row.key)}" aria-selected="${isSelected ? "true" : "false"}" title="${esc(row.label)}${row.sub ? ` (${esc(row.sub)})` : ""}">
          <span class="chrx-class-rail__label">${esc(row.label)}</span>
          ${row.sub ? `<span class="chrx-class-rail__sub" style="opacity:.6;font-size:11px;margin-left:auto;">${esc(row.sub)}</span>` : ""}
        </button>`;
      }).join("");

      classRailHtml = `
        <nav class="chrx-class-rail chrx-student-rail" aria-label="Student timetable list">
          <div class="chrx-student-search-box" style="padding:6px 8px;border-bottom:1px solid var(--chrx-border,#e2e8f0);">
            <input type="search" class="chrx-student-filter-input" data-student-filter placeholder="Search student…" aria-label="Filter students" style="width:100%;box-sizing:border-box;padding:4px 8px;font-size:12px;border:1px solid var(--chrx-border,#cbd5e1);border-radius:4px;" />
          </div>
          <div class="chrx-class-rail__list" role="tablist" aria-orientation="vertical">
            ${railItems}
          </div>
        </nav>
      `;
    }

    const pickerSearchHtml = perspective === "student"
      ? `<input type="search" class="chrx-student-picker-search" data-focus-student-search placeholder="Search student…" list="chrx-student-datalist" value="${esc(focusRow.label)}" aria-label="Search student" style="margin-left:6px;padding:3px 8px;font-size:12px;border:1px solid var(--chrx-border,#cbd5e1);border-radius:4px;" /><datalist id="chrx-student-datalist">${allRows.map(r => `<option value="${esc(r.label)}">${esc(r.sub)}</option>`).join("")}</datalist>`
      : "";

    const hintText = perspective === "student"
      ? "Student timetable is read-only. Drag is disabled."
      : perspective === "supervision"
        ? "Who is on duty where: read-only plan. \u26a0 marks a supervisor who is teaching, or booked in two areas, at that time."
        : "Drag a lesson to another period. Conflicts show in the inspector.";
    const hintClass = perspective === "student" ? "chrx-student-hint"
      : perspective === "supervision" ? "chrx-sup-hint" : "";

    return `
      <button type="button" class="chrx-skip-link chrx-sr-only" data-skip-to-grid style="position:absolute;z-index:100;padding:6px 12px;background:var(--chrx-accent,#5b6cff);color:#fff;border-radius:6px;font:600 12px var(--chrx-font-sans);border:0;cursor:pointer;">Skip to timetable</button>
      <div class="chrx-focus-boardbar">
        <button type="button" class="chrx-focus-boardbar__nav" data-focus-nav="prev" aria-label="Previous ${esc(perspective)}">${icon("chevL", 18)}</button>
        <label class="chrx-focus-boardbar__picker">
          <span>${esc(PERSPECTIVE_LABEL[perspective].replace("By ", ""))}</span>
          <select data-focus-entity aria-label="Choose ${esc(perspective)}">${options}</select>
        </label>
        ${pickerSearchHtml}
        <button type="button" class="chrx-focus-boardbar__nav" data-focus-nav="next" aria-label="Next ${esc(perspective)}">${icon("chevR", 18)}</button>
        <p class="${hintClass}">${hintText}</p>
        <button type="button" class="chrx-focus-boardbar__overview" data-focus-nav="overview">All ${esc(PERSPECTIVE_PLURAL[perspective])}</button>
      </div>
      ${selectionBarHtml()}
      ${dayTabsHtml}
      <div class="chrx-focus-workspace">
        ${classRailHtml}
        <div class="chrx-focus-board${perspective === "student" || perspective === "supervision" ? " chrx-readonly" : ""}" role="grid" aria-label="${esc(focusRow.label)} weekly timetable"
             style="--chrx-days:${isMobile ? 1 : numDays}">
          ${focusBoardInnerHtml(S, focusRow, periods, cardLookup, mobileDay, isMobile)}
        </div>
      </div>
    `;
  }

  function focusBoardInnerHtml(S, focusRow, periods, cardLookup, mobileDay, isMobileArg) {
    const numDays = dayCount(S);
    const mDay = Number.isFinite(mobileDay) ? mobileDay : ((typeof window !== "undefined" && window.APP && window.APP.day) || 0);
    const isMobile = typeof isMobileArg === "boolean" ? isMobileArg : isMobileViewport();
    const daysToRender = isMobile ? [mDay] : Array.from({ length: numDays }, (_, i) => i);
    const perspective = window.APP.editor.perspective || "class";
    const bellPeriodSet = bellSetFor(S, focusRow, perspective);
    const bucket = cardLookup[focusRow.key] || null;
    const cells = [`<div class="chrx-focus-corner" role="columnheader">Period</div>`];
    for (const day of daysToRender) {
      cells.push(`<div class="chrx-focus-day" role="columnheader" data-day="${day}">${esc(DAY_LABELS_EN[day])}</div>`);
    }
    for (const period of periods) {
      cells.push(`<div class="chrx-focus-period" role="rowheader"><strong>${esc(period.label || ("P" + period.index))}</strong><span>${esc(period.start || period.startTime || "")}</span></div>`);
      for (const day of daysToRender) {
        const cards = bucket ? bucket[day + "_" + period.index] : null;
        const outOfBell = period.synthetic || (bellPeriodSet && !bellPeriodSet.has(period.index | 0));
        const classes = ["chrx-slot", "chrx-focus-slot"];
        const supGap = perspective === "supervision" && (!cards || !cards.length);
        if (supGap) classes.push(focusRow.needsSupervision ? "chrx-sup-gap chrx-sup-gap--required" : "chrx-sup-gap");
        else if (!cards || !cards.length) classes.push("empty");
        if (outOfBell) classes.push("out-of-bell");
        if (cards && cards.length > 1) classes.push(cards.length === 2 ? "chrx-slot--split2" : "chrx-slot--split");
        const contents = cards ? cards.map(card => vkartaHtml(S, card, day, period.index, focusRow.key, 1)).join("") : "";
        const label = outOfBell ? ' aria-hidden="true"' : ` aria-label="${cards && cards.length ? "Scheduled" : (supGap ? "No supervisor" : "Empty")}, ${esc(DAY_LABELS_EN[day])} ${esc(period.label || ("period " + period.index))}"`;
        const slotTabindex = outOfBell ? "" : (!cards || !cards.length ? ' tabindex="-1"' : "");
        cells.push(`<div class="${classes.join(" ")}" role="gridcell" data-day="${day}" data-period="${period.index}" data-row="${esc(focusRow.key)}"${slotTabindex}${label}>${contents}</div>`);
      }
    }
    return cells.join("");
  }

  /* ── Overview-header stats — computed once per render, cheap. ── */
  function fillOverviewStats(rootEl, S, rows, perspective) {
    const host = rootEl.querySelector("#chrx-ob-stats");
    if (!host) return;
    const filter = currentViewFilter();
    const hidden = hiddenCardCount(S, filter);
    const unplaced = pendingCount(S);
    // "placed" counts what the grid is actually showing: with a week/term filter
    // on, quoting all 951 cards while drawing 40 would be a lie.
    const placed = visibleCardCount(S, filter);
    const days     = dayCount(S);
    const periodCount = (displayPeriods(S) || []).length;
    // Supervision counts its own plan, not the lesson grid: areas, duties,
    // duty clashes and rooms that are flagged as needing supervision but have
    // no slot at all. "placed/unplaced lessons" is meaningless here.
    let els;
    if (perspective === "supervision") {
      const sup = supervisionSummary(S);
      els = [
        stat(rows.length, (PERSPECTIVE_PLURAL[perspective] || "areas")),
        stat(days, "days"),
        stat(periodCount, "periods"),
        stat(sup.duties, "duties"),
        stat(sup.conflicts, sup.conflicts === 1 ? "conflict" : "conflicts", sup.conflicts > 0),
        stat(sup.unassigned, "unassigned", sup.unassigned > 0)
      ];
    } else {
      els = [
        stat(rows.length, PERSPECTIVE_PLURAL[perspective] || "rows"),
        stat(days, "days"),
        stat(periodCount, "periods"),
        stat(placed, "placed"),
        stat(unplaced, "unplaced", unplaced > 0)
      ];
      // Say out loud how much the filter is holding back (lane W3b-7).
      if (hidden > 0) els.push(stat(hidden, "hidden by filter", true));
    }
    host.innerHTML = els.map((e, i) => (i > 0 ? '<div class="chrx-ob-divider"></div>' : "") + e).join("");
    function stat(v, label, warn) {
      return `<div class="chrx-ob-stat${warn ? " chrx-ob-stat--warn" : ""}"><b>${esc(String(v))}</b><span>${esc(label)}</span></div>`;
    }
  }

  /* Highlight the current weekday so today's column is instantly scannable.
     Synthetic days (synthetic periods) are never treated as "today". */
  function highlightToday(rootEl, S) {
    const numDays = dayCount(S);
    // Map JS weekday (1=Mon..6=Sat) onto the timetable's own day index — if
    // the school teaches on that weekday, mark it. Noop off-school days.
    const jsDay = new Date().getDay(); // 0 = Sunday, 1 = Monday
    const todayIdx = jsDay === 0 ? -1 : jsDay - 1; // Monday=0
    if (todayIdx < 0 || todayIdx >= numDays) return;
    // Synthetic periods (lunch / break, outside bell) are never "today" —
    // skip any period marked synthetic for this day.
    const syntheticPs = (displayPeriods(S) || []).filter(p => p.synthetic).map(p => p.index | 0);
    const synSet = new Set(syntheticPs);
    rootEl.querySelectorAll(`[data-day="${todayIdx}"]`).forEach(el => {
      const p = el.dataset.period;
      if (p != null && synSet.has(p | 0)) return;
      el.classList.add("is-today");
    });
  }

  /* The rail-lift hover: cards get a class (not inline style) so the CSS
     transition controls it uniformly — no JS-driven layout thrash. */
  function enableLiftOnHover(rootEl) {
    if (rootEl.dataset.liftWired) return;
    rootEl.dataset.liftWired = "1";
    rootEl.addEventListener("pointerover", e => {
      const vk = e.target.closest(".chrx-vkarta");
      if (vk) vk.classList.add("chrx-vkarta--lift");
    });
    rootEl.addEventListener("pointerout", e => {
      const vk = e.target.closest(".chrx-vkarta");
      if (vk) vk.classList.remove("chrx-vkarta--lift");
    });
  }

  let _prevUnplaced = null;
  let _chipConflictTimer = null; // B1: debounced hard-conflict recount
  let _chipConflicts = 0; // B1: cached hard-conflict count for the chip
  function syncUnplacedCount(S) {
    const elc = document.getElementById("editor-unplaced-count");
    const n = pendingCount(S);
    if (elc) {
      // B1 — the chip is truthful and opens Verification on click.
      // Wired once; copy comes from VerificationPro.statusChipText so the
      // chip can never look "all good" while hard conflicts exist.
      if (!elc.dataset.vconfWired) {
        elc.dataset.vconfWired = "1";
        elc.style.cursor = "pointer";
        elc.setAttribute("role", "button");
        elc.setAttribute("tabindex", "0");
        const openVerification = () => window.dispatchEvent(new CustomEvent("app:verification-pro"));
        elc.addEventListener("click", openVerification);
        elc.addEventListener("keydown", e => {
          if (e.key === "Enter" || e.key === " ") { e.preventDefault(); openVerification(); }
        });
      }
      const paintChip = () => {
        const fmt = window.VerificationPro && window.VerificationPro.statusChipText;
        let text;
        if (typeof fmt === "function") {
          const s = fmt(n, _chipConflicts);
          text = s.text;
          elc.classList.toggle("is-pending", s.warn);
          elc.classList.toggle("is-conflict", s.conflict);
          elc.title = s.hint;
        } else {
          text = n === 0 ? "All placed" : n + " unplaced";
          elc.classList.toggle("is-pending", n > 0);
        }
        // This count is the FILTERED count (lane W3b-7): say so on the chip and
        // say how much the week/term filter is holding back, so a small number
        // cannot be misread as "the whole school is placed". (paintChip runs
        // twice — once now, once after the conflict recount — so the text is
        // always rebuilt from `text`, never appended to.)
        const filter = currentViewFilter();
        const filtered = filter.week !== "all" || filter.term !== "all";
        const hid = hiddenCardCount(S, filter);
        elc.textContent = filtered ? text + " · filtered" : text;
        if (hid > 0) elc.title = `${elc.title || ""} — ${hid} card(s) hidden by the week/term filter`.trim();
      };
      paintChip();
      // B1 — cheap: reuse the panel's verifier, debounced, on the same
      // events that update the count (render / patchCells call here).
      if (_chipConflictTimer) clearTimeout(_chipConflictTimer);
      _chipConflictTimer = setTimeout(() => {
        try {
          const c = window.VerificationPro && window.VerificationPro.countHardConflicts
            ? window.VerificationPro.countHardConflicts(S) : 0;
          _chipConflicts = typeof c === "number" ? c : 0;
        } catch (_) { _chipConflicts = 0; }
        paintChip();
      }, 300);
    }
    // Plan D: celebrate the moment everything first lands (a real >0 → 0
    // transition, not an already-complete load). Never while a week/term filter
    // is on: that count is the filtered count, so filtering the view would fire
    // a ticker-tape for work that is still unplaced in the school.
    const viewFilter = currentViewFilter();
    const filtered = viewFilter.week !== "all" || viewFilter.term !== "all";
    if (!filtered && _prevUnplaced != null && _prevUnplaced > 0 && n === 0) celebrateAllPlaced();
    _prevUnplaced = n;
  }

  // One-shot confetti burst. Pure canvas, no deps; honours reduced-motion and
  // won't stack if one is already running.
  function celebrateAllPlaced() {
    if (document.getElementById("chrx-confetti")) return;
    if (typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const cv = document.createElement("canvas");
    cv.id = "chrx-confetti";
    cv.style.cssText = "position:fixed;inset:0;pointer-events:none;z-index:10020";
    cv.width = window.innerWidth; cv.height = window.innerHeight;
    document.body.appendChild(cv);
    const ctx = cv.getContext("2d");
    const colors = ["#0d4f54", "#b08a3e", "#9c4322", "#5b6e3d", "#4c6e91", "#d9466b"];
    const parts = Array.from({ length: 150 }, () => ({
      x: cv.width / 2 + (Math.random() - 0.5) * 160,
      y: cv.height / 3,
      vx: (Math.random() - 0.5) * 11,
      vy: Math.random() * -13 - 4,
      r: 4 + Math.random() * 5,
      c: colors[(Math.random() * colors.length) | 0],
      rot: Math.random() * 6, vr: (Math.random() - 0.5) * 0.4,
    }));
    let frames = 0;
    (function frame() {
      frames++;
      ctx.clearRect(0, 0, cv.width, cv.height);
      let alive = false;
      for (const p of parts) {
        p.vy += 0.35; p.x += p.vx; p.y += p.vy; p.rot += p.vr;
        if (p.y < cv.height + 24) alive = true;
        ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.rot);
        ctx.fillStyle = p.c; ctx.fillRect(-p.r / 2, -p.r / 2, p.r, p.r * 0.6); ctx.restore();
      }
      if (alive && frames < 240) requestAnimationFrame(frame);
      else cv.remove();
    })();
  }

  const PERSPECTIVES = ["class", "teacher", "room", "subject", "student", "supervision"];
  const PERSPECTIVE_LABEL = { class: "By Class", teacher: "By Teacher", room: "By Room", subject: "By Subject", student: "By Student", supervision: "By Supervision" };
  const PERSPECTIVE_PLURAL = { class: "classes", teacher: "teachers", room: "rooms", subject: "subjects", student: "students", supervision: "areas" };
  const COLOR_AXES = ["subject", "teacher", "class", "room"];
  const COLOR_LABEL = { subject: "Color: Subject", teacher: "Color: Teacher", class: "Color: Class", room: "Color: Room" };

  function icon(name, size) {
    return window.ChrxIcons ? window.ChrxIcons.svg(name, size || 16) : "";
  }

 function pendingCount(S) {
   const filter = currentViewFilter();
   const placed = Object.create(null);
   for (const c of (S.cards || [])) placed[c.lessonId] = (placed[c.lessonId] || 0) + 1;
   let total = 0;
   for (const L of (S.lessons || [])) {
     // Work the week/term filter hides is not "unplaced" in the view you asked
     // for — the tray, the chip and the class rail all follow the filter.
     if (!lessonMatchesFilter(L, filter, S)) continue;
     const len = L.lessonLength || (L.isLabDouble ? 2 : 1);
     const ppw = Math.ceil(L.periodsPerWeek || 0);
     const needed = ppw > 0 ? Math.max(1, Math.round(ppw / len)) : 0;
     total += Math.max(0, needed - (placed[L.id] || 0));
   }
   return total;
 }

  function dayTabsHtml_(mobileDay, numDays) {
    const tabs = DAY_LABELS_EN.slice(0, numDays || NUM_DAYS).map((label, d) =>
      `<button class="chrx-day-tab ${d === mobileDay ? "active" : ""}" data-day="${d}" type="button" role="tab" aria-selected="${d === mobileDay ? "true" : "false"}" aria-label="${esc(label)}">${esc(label)}</button>`
    ).join("");
    return `<div class="chrx-day-tabs" role="tablist" aria-label="Days of week">${tabs}</div>`;
  }

  function headerRowHtml(periods, mobileDay, numDays) {
    const dayBlocks = [];
    for (let d = 0; d < numDays; d++) {
      const cells = periods.map(p =>
        `<div class="chrx-h chrx-h-period${p.synthetic ? " is-synthetic" : ""}" data-day="${d}" data-period="${p.index}">${esc(p.label || ("P" + p.index))}</div>`
      ).join("");
      dayBlocks.push(`
        <div class="chrx-day-head-group ${d !== mobileDay ? "mobile-hidden" : ""}" data-day="${d}">
          <div class="chrx-h-day" data-day="${d}">${esc(DAY_LABELS_EN[d])}</div>
          <div class="chrx-period-head-row">${cells}</div>
        </div>
      `);
    }
    return `
      <div class="chrx-row chrx-row-head" data-row="head">
        <div class="chrx-rowlabel chrx-h">${esc(PERSPECTIVE_LABEL[(window.APP.editor && window.APP.editor.perspective) || "class"].replace("By ", ""))}</div>
        ${dayBlocks.join("")}
      </div>
    `;
  }

  function bellSetFor(S, row, persp) {
    if (persp === "class" && window.BellResolver) {
      const bell = window.BellResolver.forClass(S, row.key);
      if (bell && Array.isArray(bell.periods)) {
        return new Set(bell.periods.map(p => p.index | 0));
      }
    }
    if (persp === "student" && window.BellResolver && row) {
      const students = (S && S.students) || [];
      const st = students.find(s => s.id === row.key);
      if (st && st.classId) {
        const bell = window.BellResolver.forClass(S, st.classId);
        if (bell && Array.isArray(bell.periods)) {
          return new Set(bell.periods.map(p => p.index | 0));
        }
      }
    }
    return null;
  }

  function rowHtml(S, row, periods, mobileDay, cardLookup, numDays) {
    const rowBucket = cardLookup[row.key] || null;
    const dayBlocks = [];
    const persp = (window.APP && window.APP.editor && window.APP.editor.perspective) || "class";
    const selected = persp === "class" && window.APP.editor && window.APP.editor.selectedClassId === row.key;
    const bellPeriodSet = bellSetFor(S, row, persp);
    for (let d = 0; d < numDays; d++) {
      dayBlocks.push(`
        <div class="chrx-day-body-group ${d !== mobileDay ? "mobile-hidden" : ""}" data-day="${d}">
          ${dayBodyHtml(S, row, periods, d, rowBucket, bellPeriodSet)}
        </div>
      `);
    }
    return rowTailHtml(row, selected, dayBlocks);
  }

  // All slots for one (row, day) — shared by the full render (rowHtml) and
  // the incremental post-drag patch (Editor.patchCells), so span2 / split /
  // out-of-bell rendering can never drift between the two paths.
  function dayBodyHtml(S, row, periods, d, rowBucket, bellPeriodSet) {
    const slots = [];
    // Supervision is a duty plan, not a lesson grid: a cell with no chip is a
    // gap (nobody on duty). Gaps get `chrx-sup-gap` instead of `empty` so the
    // empty-cell right-click "place lesson here" picker and the drop-on-empty
    // path stay out of a read-only view; `--required` marks a classroom whose
    // own record is flagged needsSupervision.
    const supPersp = (window.APP && window.APP.editor && window.APP.editor.perspective) === "supervision";
    const gapClass = "chrx-sup-gap" + (row.needsSupervision ? " chrx-sup-gap--required" : "");
    for (let pi = 0; pi < periods.length; pi++) {
      const p = periods[pi];
      const cards = rowBucket ? rowBucket[d + "_" + p.index] : null;
      const outOfBell = p.synthetic || (bellPeriodSet && !bellPeriodSet.has(p.index | 0));
      if (cards && cards.length > 0) {
        const oob = outOfBell ? " out-of-bell" : "";
        // Exactly two cards share a cell (a group-split, or a conflict in
        // teacher/room view) → render as a clean DIAGONAL split (aSc-style)
        // via chrx-slot--split2. Three or more fall back to the micro-card
        // grid (chrx-slot--split).
        const splitClass = cards.length === 2 ? " chrx-slot--split2"
                         : cards.length > 2  ? " chrx-slot--split" : "";
        // Double-period BLOCK: only merge two consecutive cards into a
        // single 2-wide block when the lesson is a real lab-double
        // (isLabDouble=true — aSc's periodspercard=2, e.g. Sports Meet at
        // periods 1 AND 2). Render the first spanning two columns and
        // SKIP the second so it reads as a single block. Without the
        // isLabDouble gate, two SOLVER-PLACED single-period cards of the
        // same lesson (e.g. English II B landing on Tue P6+P7 by
        // accident) also got fused into a fake block — hiding the bug.
        // Fallback: a lone lab-double card with an empty next cell still
        // expands to fill its block.
        const thisCard = cards.length === 1 ? cards[0] : null;
        const firstLesson = thisCard ? S._idx.lessonById[thisCard.lessonId] : null;
        const nextP = periods[pi + 1];
        const nextBucket = (nextP && rowBucket) ? rowBucket[d + "_" + nextP.index] : null;
        const nextSameLesson = !!(thisCard && nextBucket && nextBucket.length === 1
          && nextBucket[0].lessonId === thisCard.lessonId);
        const nextEmpty = !!(nextP && !nextBucket);
        const isLab = !!(firstLesson && firstLesson.isLabDouble
          && (nextSameLesson || nextEmpty));
        const spanClass = isLab ? " chrx-slot--span2" : "";
        const cardListHtml = cards.map(c => vkartaHtml(S, c, d, p.index, row.key, isLab ? 2 : 1)).join("");
        slots.push(
          `<div class="chrx-slot${oob}${splitClass}${spanClass}" role="gridcell" data-day="${d}" data-period="${p.index}" data-row="${esc(row.key)}">${cardListHtml}</div>`
        );
        if (isLab) pi++; // the block covers the next period too — skip it
      } else {
        const oob = outOfBell ? " out-of-bell" : "";
        const emptyCls = supPersp ? gapClass : "empty";
        slots.push(
          `<div class="chrx-slot ${emptyCls}${oob}" role="gridcell" data-day="${d}" data-period="${p.index}" data-row="${esc(row.key)}"${outOfBell ? ' aria-hidden="true"' : ` aria-label="${supPersp ? "No supervisor" : "Empty"}, ${esc((DAY_LABELS_EN[d]||("Day "+(d+1))))} period ${p.index}"`}></div>`
        );
      }
    }
    return slots.join("");
  }

  function rowTailHtml(row, selected, dayBlocks) {
    return `
      <div class="chrx-row${selected ? " chrx-row--selected" : ""}" data-row="${esc(row.key)}">
        <div class="chrx-rowlabel" title="${esc(row.label)}" role="button" tabindex="0" aria-pressed="${selected ? "true" : "false"}">
          <span class="chrx-rowlabel-main">${esc(row.label)}</span>
          ${row.sub ? `<span class="chrx-rowlabel-sub">${esc(row.sub)}</span>` : ""}
        </div>
        ${dayBlocks.join("")}
      </div>
    `;
  }

  // A compact card code for the narrow By-Class cells. Prefer the school's own
  // short abbreviation; if it's missing or just equals the full name (so it
  // would wrap/clip in a ~30px cell), derive one: keep already-short names
  // as-is (GK, E.V.S, I.T), initial-ise multi-word names (Sports Meet
  // Practice → SMP), and take a 3-letter stem of a single long word
  // (Maths → Mat). The full name stays in the hover tooltip + card detail, so
  // nothing is lost — this only governs the at-a-glance text in the cell.
  function subjectCode(subject) {
    const S = window.APP && window.APP.school;
    const uniq = S ? uniqueCodes(S) : null;
    if (uniq && subject && uniq.has(subject.id)) return uniq.get(subject.id);
    const forms = shortForms(subject);
    return forms[0] || baseSubjectCode(subject);
  }

  const CODE_STOPWORDS = /^(of|the|and|&|period|pd|a)$/i;
  // A code has to FIT. Uniqueness as a string is not enough: "Fn. English",
  // "Fn. EVS", "Fn. SST" and "Fn. Science" are four distinct strings that all
  // clip to the same visible text ("Fn. ") in a narrow cell — measured on the
  // demo school, 174 of 971 labels were clipped and those four subjects were
  // indistinguishable on screen. Capping every candidate at four characters
  // keeps a code inside the cell instead of relying on the clip.
  const MAX_CODE_LEN = 4;

  // Every short form a subject could render, most→least informative.
  function shortForms(subject) {
    const name = (subject.name || subject.abbr || "?").trim();
    const abbr = (subject.abbr || "").trim();
    const bareName = name.replace(/[^A-Za-z0-9]/g, "").toUpperCase();
    const out = [];
    // The school's own abbreviation wins while it is short enough to fit AND
    // still says something the full name doesn't.
    if (abbr && abbr.toUpperCase() !== bareName && abbr.length <= MAX_CODE_LEN) out.push(abbr);
    const words = name.split(/\s+/).filter(w => w && !CODE_STOPWORDS.test(w));
    if (words.length >= 2) out.push(words.map(w => w[0].toUpperCase()).join("").slice(0, MAX_CODE_LEN));
    const w0 = (words[0] || name).replace(/[^A-Za-z0-9]/g, "");
    for (let len = Math.min(MAX_CODE_LEN, w0.length); len >= 2; len--) out.push(w0.slice(0, len));
    return [...new Set(out.filter(Boolean))];
  }

  // The code a subject would get in isolation. Correct on its own, but two
  // subjects can land on the same one — see uniqueCodes().
  function baseSubjectCode(subject) {
    const name = (subject.name || subject.abbr || "?").trim();
    const abbr = (subject.abbr || "").trim();
    // Respect the school's own abbreviation whenever it's a real, distinct code
    // (the user asked to "use the abbreviations that are already there"). Only
    // when there's no real abbr — it's missing or just repeats the full name —
    // do we derive a tidy one so the card doesn't show a clipped full word.
    if (abbr && abbr !== name) return abbr;
    const bare = name.replace(/[.\s]/g, "");
    if (bare.length <= 4) return name;                  // already short: GK, E.V.S, S.S.T
    const words = name.split(/\s+/).filter(w => !/^(of|the|and|&|period|pd|a)$/i.test(w));
    if (words.length >= 2) return words.map(w => w[0].toUpperCase()).join("").slice(0, 4);
    return name[0].toUpperCase() + name.slice(1, 3).toLowerCase();   // Maths → Mat
  }

  // Codes must identify ONE subject. Initials collide easily: the demo school
  // has "Foundation English" and "Foundation EVS" (both → FE) and "Foundation
  // SST" / "Foundation Science" (both → FS), so four rows of the grid were
  // genuinely ambiguous — the same code meant two different subjects, and no
  // amount of hovering fixes a code you cannot trust at a glance.
  // Colliding subjects are extended by letters taken from their own last word
  // until each is distinct (FE → FEN / FEE), capped so a code stays glanceable;
  // a numeric tiebreak is the last resort so uniqueness is guaranteed.
  // Memoized per school so this costs nothing per card.
  let _codeMap = null, _codeMapKey = "";
  let _ambiguous = null;
  function uniqueCodes(S) {
    const subjects = (S && S.subjects) || [];
    // Signature covers names, not just the count: renaming or re-abbreviating a
    // subject must invalidate the map without changing how many there are.
    let sig = (S && S.id ? S.id : "") + "|" + subjects.length;
    for (let i = 0; i < subjects.length; i++) {
      sig += "|" + (subjects[i].name || "") + "~" + (subjects[i].abbr || "");
    }
    if (_codeMap && _codeMapKey === sig) return _codeMap;

    // Count how many subjects can produce each short form. A form claimed by
    // more than one subject is ambiguous and must never be shown.
    const formsById = new Map();
    const owners = new Map();
    subjects.forEach(s => {
      const forms = shortForms(s);
      formsById.set(s.id, forms);
      forms.forEach(f => {
        if (!owners.has(f)) owners.set(f, new Set());
        owners.get(f).add(s.id);
      });
    });
    const ambiguous = new Set();
    owners.forEach((ids, form) => { if (ids.size > 1) ambiguous.add(form); });

    // Prefer each subject's most informative form that no other subject can
    // produce. When every form collides, the subjects sharing that base are
    // resolved AS A GROUP — see below.
    const map = new Map();
    const contested = new Map();   // base form -> [subjects that fell back to it]
    subjects.forEach(s => {
      const forms = formsById.get(s.id) || [];
      const pick = forms.find(f => owners.get(f).size === 1) || null;
      if (pick) { map.set(s.id, pick); return; }
      const base = forms[0] || baseSubjectCode(s);
      if (!contested.has(base)) contested.set(base, []);
      contested.get(base).push(s);
    });

    // A group sharing a base (six "Foundation …" subjects all reduce to FE/FS/FM/FH)
    // is resolved together, and the base SHRINKS TO ONE LETTER so the result still
    // fits a narrow cell.
    //
    // The arithmetic is what forces this: "Foundation English" and "Foundation EVS"
    // both begin with E, so one suffix letter cannot separate them — two are needed.
    // Keeping the two-letter base then yields four-character codes (FEEn/FEEV) that
    // clip to the same visible "FEE". Dropping the base to its first letter gives
    // FEn / FEV / FSc / FSS: three characters, distinct, and inside the cell.
    // Deciding per-subject in isolation is what produced the four-char codes in the
    // first place (the first subject took the short code, forcing the second to
    // grow), so this must stay group-aware.
    contested.forEach((members, base) => {
      const suffixOf = (s) => {
        const words = (s.name || s.abbr || "").split(/\s+/)
          .filter(w => w && !CODE_STOPWORDS.test(w));
        const raw = String(words.length > 1 ? words[words.length - 1] : words[0] || "");
        return raw.replace(/[^A-Za-z0-9]/g, "");
      };
      const suffixes = members.map(suffixOf);
      // Only shrink when the group actually needs more than one suffix letter.
      const needsGrowth = suffixes.some((o, i) =>
        suffixes.some((p, j) => j !== i && o[0] === p[0]));
      const stem = needsGrowth && base.length > 1 ? base[0] : base;
      members.forEach((s, i) => {
        const mine = suffixes[i];
        let pick = null;
        // Every candidate is length-capped. Without this, a group whose suffixes
        // share no first letter kept the full 4-char base and appended a suffix
        // on top — "MATHS" vs "MATHS LAB PERIOD" (whose every form collides)
        // produced MATHM/SporS, five characters that overflow a ~37px cell. The
        // stem is trimmed per suffix length so the total never exceeds the cap.
        const stemFor = (k) => stem.slice(0, Math.max(1, MAX_CODE_LEN - k));
        for (let k = 1; k <= mine.length && !pick; k++) {
          // Unique within the group AND not claimed by any subject outside it.
          const cand = stemFor(k) + mine.slice(0, k);
          const shared = suffixes.some((o, j) => j !== i && o.slice(0, k) === mine.slice(0, k));
          if (!shared && !owners.has(cand)) pick = cand;
        }
        // Degenerate cases: identical names, or more members than the alphabet
        // can separate at this length.
        if (!pick) {
          for (let k = 1; k <= mine.length && !pick; k++) {
            const cand = stemFor(k) + mine.slice(0, k);
            if (!owners.has(cand)) pick = cand;
          }
        }
        if (!pick) {
          for (let n = 2; n < 100 && !pick; n++) {
            const cand = base.slice(0, Math.max(1, MAX_CODE_LEN - String(n).length)) + n;
            if (!owners.has(cand)) pick = cand;
          }
        }
        if (!pick) pick = base.slice(0, MAX_CODE_LEN);
        owners.set(pick, new Set([s.id]));
        map.set(s.id, pick);
      });
    });

    _ambiguous = ambiguous;
    _codeMap = map; _codeMapKey = sig;
    return map;
  }

  // Candidate forms of a subject label, most→least informative, used when the
  // preferred code overflows the actual cell width. The unique code leads, every
  // form some OTHER subject could also produce is dropped, and then the code's
  // own leading substrings are appended as last-resort rungs.
  //
  // Why the extra rungs: uniqueness is computed from every form a subject COULD
  // produce, not from the code it actually renders, so it rejects harmless
  // shortenings — "MATHS" renders MATM and "MATHS LAB PERIOD" renders ML, yet
  // the ladder for MATHS was [MATM] alone because "MAT" is a form both subjects
  // could produce. With no shorter rung the fit pass had nothing to fall back to
  // and the 4-character code was cut mid-glyph to "MA" in a 19px cell — a string
  // that reads as a real 2-character code. A rung is only offered when it cannot
  // be mistaken for another subject's rendered code: it must not equal one and
  // must not be the beginning of one (so "FE" is still refused for Foundation
  // English, whose siblings render FEn/FEV — the four-“Fn.”-subjects fix holds).
  function codeCandidates(subject) {
    const S = window.APP && window.APP.school;
    if (S) uniqueCodes(S);
    const preferred = subjectCode(subject);
    const ambiguous = _ambiguous || new Set();
    const out = [preferred];
    shortForms(subject).forEach(c => {
      if (!ambiguous.has(c) && !out.includes(c)) out.push(c);
    });
    for (let n = preferred.length - 1; n >= 2; n--) {
      const cand = preferred.slice(0, n);
      if (out.includes(cand)) continue;
      if ((S && codeConflicts(S, cand, subject)) || (!S && ambiguous.has(cand))) continue;
      out.push(cand);
    }
    return out.filter(Boolean);
  }

  // True when `cand` would be confusable with the code another subject renders.
  function codeConflicts(S, cand, subject) {
    for (const other of (S.subjects || [])) {
      if (!other || other.id === subject.id) continue;
      const code = subjectCode(other);
      if (code === cand || code.indexOf(cand) === 0) return true;
    }
    return false;
  }

  // Post-render pass: fit every card's primary line into its cell. The school's
  // abbreviation is preferred, but if it still overflows at the rendered font we
  // walk a ladder of shorter codes, and only then shrink the type.
  //
  // The original pass CLIPPED (text-overflow: clip) whenever no ladder candidate
  // fitted, and it skipped "far" zoom entirely on the assumption that level drew
  // no text — it draws the subject code now, so Compact was the WORST level on
  // screen (482 of 971 labels cut, 49.6%) while being the densest. A hard cut is
  // also never acceptable on its own terms: "MATM" rendered as "MA", "URDU" as
  // "UR", "Sports" as "Spo" — each reads as a real, different code.
  // Measured with canvas (accurate, reflow-free). By-Class only — other
  // perspectives carry class lists that legitimately wrap.
  const FIT_MIN_PX = 8.5;    // below this a 1-line code stops being readable
  const FIT_COMFORT_PX = 10; // prefer a shorter rung over type smaller than this
  const FIT_MIN_CHARS = 3;   // the code floor: 3 characters identify a subject
  const FIT_STEP_PX = 0.5;

  function autoFitSubjectCodes(rootEl, scopeEl) {
    if (!rootEl || (window.APP.editor.perspective || "class") !== "class") return;
    // Focus view prints the FULL subject name and wraps it to two lines — that is
    // its design, so the code-fitting pass stays out of it.
    if (window.APP.editor.viewMode === "focus") return;
    const S = window.APP && window.APP.school;
    if (!S) return;
    const scope = scopeEl || rootEl;
    const slot = scope.querySelector(".chrx-slot:not(.empty)");
    const lines = scope.querySelectorAll(".chrx-vk-line1");
    if (!slot || !lines.length) return;
    const cs = getComputedStyle(lines[0]);
    const fam = cs.fontFamily || "sans-serif";
    const weight = cs.fontWeight || "700";
    const fontPx = parseFloat(cs.fontSize) || 11.5;
    const slotW = Math.max(10, slot.clientWidth - 12);
    const ctx = (autoFitSubjectCodes._c || (autoFitSubjectCodes._c = document.createElement("canvas").getContext("2d")));
    const wOf = (t, size) => { ctx.font = `${weight} ${size || fontPx}px ${fam}`; return ctx.measureText(t).width; };
    // Measure every target BEFORE writing anything: the write pass below mutates
    // text and font, which invalidates layout, so interleaving the two would
    // force a reflow per card. 971 cards must stay one layout.
    //
    // Per-element widths, not one width for the whole grid: a split cell (two
    // co-taught subjects stacked) is 7px narrower than a plain one, and measuring
    // the first line only meant 'Sans' was kept at 22px inside an 18px box — the
    // last 37 mid-glyph cuts on Compact.
    const targets = [];
    for (const el of lines) {
      const card = el.closest(".chrx-vkarta");
      const lesson = card && S._idx.lessonById[card.dataset.lessonId];
      const subject = lesson && S._idx.subjectById[lesson.subjectId];
      targets.push({
        el, subject,
        avail: Math.max(10, el.clientWidth || slotW),
        size: parseFloat(getComputedStyle(el).fontSize) || fontPx,
      });
    }
    const cache = new Map();
    for (const { el, subject, avail, size } of targets) {
      // Reset whatever a previous pass (or a post-drag re-fit of this row) left
      // behind, so the pass is idempotent and always re-measures the natural code.
      el.style.fontSize = "";
      el.style.textOverflow = "";
      delete el.dataset.fit;
      if (!subject) continue;
      const preferred = subjectCode(subject);
      if (el.textContent !== preferred) el.textContent = preferred;
      let ladder = cache.get(subject.id);
      if (!ladder) { ladder = codeCandidates(subject); cache.set(subject.id, ladder); }
      // Largest font size at which `cand` fits, from `size` down to `floor`; null
      // when it cannot be shown whole at any size we are willing to print.
      const sizeFor = (cand, floor) => {
        for (let s = size; s >= floor; s -= FIT_STEP_PX) {
          if (wOf(cand, s) <= avail) return s;
        }
        return null;
      };
      // Largest size at which each rung fits whole, or null when it cannot be
      // shown at any size we are willing to print.
      const sizes = ladder.map(c => [c, sizeFor(c, FIT_MIN_PX)]);
      // A rung below the 3-character floor is only a candidate when it IS the
      // subject's own code — GK, ML, FM, LA are genuinely two characters, and a
      // derived 4-character stem must never outrank them.
      const long = sizes.filter(([c]) => c.length >= FIT_MIN_CHARS || c === preferred);
      // Pick the biggest size in a pool, breaking ties by the ladder's order
      // (most informative first).
      const pickFrom = (pool, floor) => {
        let best = null;
        for (const [cand, s] of pool) {
          if (s === null || s < floor) continue;
          if (!best || s > best[1]) best = [cand, s];
        }
        return best;
      };
      // The rounds, in the order the cell should sacrifice information: hold the
      // 3-character floor while it is still readable, then prefer readable type
      // over characters, then the floor, then a shorter code. Nothing fits whole
      // at all → the ellipsis branch below, never a silent mid-glyph cut.
      const chosen = pickFrom(long, FIT_COMFORT_PX) || pickFrom(sizes, FIT_COMFORT_PX) ||
                     pickFrom(long, FIT_MIN_PX) || pickFrom(sizes, FIT_MIN_PX);
      if (chosen) {
        const [cand, s] = chosen;
        if (el.textContent !== cand) el.textContent = cand;
        if (s < size) {
          el.style.fontSize = s + "px";
          el.dataset.fit = "shrink";
        }
        continue;
      }
      // Nothing fits whole even at the floor: the shortest rung plus an ellipsis,
      // so the cell reads as abbreviated rather than as a wrong code.
      const shortest = ladder[ladder.length - 1] || preferred;
      if (el.textContent !== shortest) el.textContent = shortest;
      el.style.fontSize = FIT_MIN_PX + "px";
      el.style.textOverflow = "ellipsis";
      el.dataset.fit = "truncate";
    }
  }

  function vkartaHtml(S, card, day, period, rowKey, blockLen) {
    // Supervision chips are not timetable cards (Lane W3b-5): they report who
    // is on duty and which duty clashes.  They deliberately render without the
    // `.chrx-vkarta` class, so pickup, drag, double-click, context-menu and the
    // card keyboard path cannot touch them — the view is read-only by
    // construction, with the edit path left to the Supervisions entity dialog.
    if (card && card.supervision) {
      // Overview cells are ~30px wide: same reason the lesson grid shows subject
      // codes there.
      return supervisionChipHtml(card, S, { compact: window.APP.editor.viewMode !== "focus" });
    }
    const lesson = S._idx.lessonById[card.lessonId];
    const subject = lesson ? S._idx.subjectById[lesson.subjectId] : null;
    const subjShort = subject ? (subject.abbr || subject.name) : "?";
    const subjCode = subject ? subjectCode(subject) : "?";
    // Full name for the PROMINENT line — wrapped to 2 lines it reads better
    // than a cramped abbr ("Sports Meet" vs "Spo Me"), aSc-style but breaking
    // on word boundaries rather than mid-word.
    const subjFull = subject ? (subject.name || subject.abbr) : "?";
    const teacherShort = (lesson?.teacherIds || [])
      .map(tid => S._idx.teacherById[tid])
      .filter(Boolean)
      .map(t => t.abbr || t.name)
      .join(", ");
    // Dense cells need an even shorter teacher form. Every teacher in the demo
    // school carries abbr === name ("Mr. Zaid"), so the abbr path yields nothing
    // shorter — and in a ~35px cell the honorific is what eats the space while
    // being the least informative token. Dropping it is what makes the near-zoom
    // second line readable ("Zaid") instead of clipped ("Mr. Z").
    const teacherCompact = (lesson?.teacherIds || [])
      .map(tid => S._idx.teacherById[tid])
      .filter(Boolean)
      .map(t => String(t.abbr || t.name).replace(/^(mr|mrs|ms|miss|dr|shri|smt|sri)\.?\s+/i, ""))
      .filter(Boolean)
      .join(", ");
    const roomShort = (() => {
      const rid = card.classroomId || lesson?.preferredRoomId;
      const r = rid ? S._idx.classroomById[rid] : null;
      return r ? r.name : "";
    })();
    const classShort = (() => {
      if (window.APP.editor.perspective === "class") return ""; // already row
      return (lesson?.classIds || [])
        .map(cid => S._idx.classById[cid])
        .filter(Boolean)
        .map(c => c.name)
        .join(", ");
    })();

    const hue = cardHue(S, card, lesson, subject);
    // In Color:Teacher mode a lesson with N teachers (Sci Lab = 3 teachers,
    // Activity = 6+) renders as N diagonal stripes, one band per teacher's
    // colour (aSc-style). Single-teacher cards stay a flat colour.
    let stripeBg = null;
    if ((window.APP.editor.colorBy || "subject") === "teacher" &&
        lesson && (lesson.teacherIds || []).length >= 2) {
      const hues = lesson.teacherIds.map(tid => {
        const t = S._idx.teacherById[tid];
        const h = t && hexHue(t.color);
        return h == null ? hashHue(t && (t.abbr || t.name || tid)) : h;
      });
      stripeBg = teacherStripes(hues);
    }
    const cardId = `placed_${card.lessonId}_${day}_${period}`;
    const persp = window.APP.editor.perspective;
    const locked = (card.locked || lesson?.fixedDay != null || lesson?.fixedPeriod != null) ? " locked" : "";
    // Prominent (line1) text is the field that VARIES within this row — the
    // row's own dimension is already known, so repeating it big is wasted
    // space (aSc does the same). In a teacher row every card is that teacher,
    // so the class is what matters; in a class row the subject varies; etc.
    //   class   row → subject (classes are fixed) | then teacher, room
    //   teacher row → class   (teacher is fixed)  | then subject, room
    //   room    row → subject + class             | then teacher
    //   subject row → class   (subject is fixed)  | then teacher, room
    // Cell shows the prominent (varying) field + ONE secondary line — aSc-clean.
    // The room/third field lives in the hover tooltip + card-detail panel, so
    // the cell isn't a clipped 3-line cram.
    let line1, line2;
    const zoom = currentZoom();
    const inFocus = window.APP.editor.viewMode === "focus";
    if (persp === "teacher") { line1 = classShort || subjShort; line2 = subjShort; }
    else if (persp === "subject") { line1 = classShort || teacherShort; line2 = teacherShort; }
    else if (persp === "room") { line1 = subjFull; line2 = classShort; }
    else if (persp === "student") {
      line1 = inFocus ? subjFull : (zoom === "far" ? subjCode : subjFull);
      line2 = [teacherShort, roomShort].filter(Boolean).join(" · ");
    }
    // By-Class: a compact subject CODE is enough at the working zoom (the class
    // is the row and colour already encodes the subject) — aSc uses short codes
    // here for exactly this reason, since a ~28-38px cell cannot show a full
    // name. subjectCode() prefers the school's own abbr and falls back to a
    // derived, uniqueness-checked code; the full name stays in the hover tooltip,
    // the card-detail panel and the code legend.
    else {
      if (inFocus) {
        line1 = subjFull;
        line2 = [teacherShort, roomShort].filter(Boolean).join(" · ");
      } else if (zoom === "far") {
        // aSc density mode (26px row pitch): crisp subject code, fits full school
        line1 = subjCode;
        line2 = "";
      } else if (zoom === "near") {
        // Reading zoom: spend the extra row height on the fields you would
        // otherwise have to hover for. Still the code, not the full name — the
        // cell is no wider here, so a name would only clip.
        line1 = subjCode;
        line2 = [teacherCompact, roomShort].filter(Boolean).join(" · ");
      } else {
        line1 = subjCode;
        line2 = "";
      }
    } // class
    // Zoom reaches the card so CSS never has to infer it from the density flag.
    const zoomClass = inFocus ? "" : " chrx-vkarta--zoom-" + zoom;

    // No native title attribute — ConstraintExplainer renders the single
    // rich hover tooltip (info header + violations). A title here made the
    // browser's native tooltip overlap the explainer with duplicate text.
    const bgStyle = stripeBg ? `;background:${stripeBg};border-left-color:transparent` : "";
    // Screen-reader label: the full human description regardless of how the cell
    // is abbreviated visually (Plan E a11y). e.g. "Maths, X A, Ms. Yachna —
    // Monday period 3, locked".
    const dayName = DAY_LABELS_EN[day] || ("Day " + (day + 1));
    const ariaLabel = [subjFull, classShort, teacherShort, roomShort]
      .filter(Boolean).join(", ") + ` — ${dayName} period ${period}` + (locked ? ", locked" : "");
    return `
      <div class="chrx-vkarta${locked}${zoomClass}"
           data-card-id="${cardId}"
           data-lesson-id="${esc(card.lessonId)}"
           data-day="${day}"
           data-period="${period}"
           data-block-len="${blockLen || 1}"
           data-classroom-id="${esc(card.classroomId || "")}"
           role="button" tabindex="0" aria-label="${esc(ariaLabel)}"
           aria-roledescription="timetable card"
           style="--chrx-card-hue:${hue}${bgStyle}">
        ${line1 ? `<div class="chrx-vk-line1">${esc(line1)}</div>` : ""}
        ${line2 ? `<div class="chrx-vk-line2">${esc(line2)}</div>` : ""}
      </div>
    `;
  }

  function wire(rootEl) {
    // Pointer delegation is wire-once: rootEl is the same node across
    // re-renders (only innerHTML is replaced — child listeners die, but
    // listeners on rootEl itself accumulate). Before this guard, every
    // pick/place re-render attached another handler, so a
    // normal edit session leaked hundreds of listeners until the tab froze.
    if (!rootEl._chrxWired) {
      rootEl.addEventListener("pointerdown", onPointerDown);
      rootEl.addEventListener("touchstart", onSwipeStart, { passive: true });
      // Day-tab click delegation off rootEl too — survives innerHTML
      // replace without needing a re-bind every render.
      rootEl.addEventListener("click", onRootClick);
      rootEl.addEventListener("change", onRootChange);
      rootEl.addEventListener("input", onRootInput);
      rootEl.addEventListener("mouseover", onMouseOver);
      rootEl.addEventListener("focusin", onFocusIn);
      rootEl.addEventListener("mouseout", onMouseOut);
      wireKeyboardNav(rootEl);
      // Clipboard and Escape also work while focus is on a slot or card after
      // a re-render; the document listener avoids depending on a particular
      // child retaining focus.
      if (typeof document !== "undefined" && !document._chrxSelectionShortcuts) {
        document.addEventListener("keydown", onSelectionShortcut, true);
        document._chrxSelectionShortcuts = true;
      }

      // Re-render when breakpoint changes between phone single-day and desktop multi-day,
      // or on device orientation change / window resize.
      if (typeof window !== "undefined") {
        const triggerReRender = () => {
          const host = document.querySelector(".chrx-editor");
          if (host && window.APP && window.APP.school) {
            render(host);
          }
        };
        if (typeof window.matchMedia === "function") {
          const mql = window.matchMedia("(max-width: 767px)");
          if (typeof mql.addEventListener === "function") {
            mql.addEventListener("change", triggerReRender);
          } else if (typeof mql.addListener === "function") {
            mql.addListener(triggerReRender);
          }
        }
        let resizeTimer = null;
        const onResize = () => {
          if (resizeTimer) clearTimeout(resizeTimer);
          resizeTimer = setTimeout(triggerReRender, 100);
        };
        window.addEventListener("resize", onResize, { passive: true });
        window.addEventListener("orientationchange", onResize, { passive: true });
      }

      // Plan C: pinch-to-zoom the grid (scales cell width + row height via the
      // --chrx-grid-zoom var, sticky-safe — no transform).
      let pinch = null;
      rootEl.addEventListener("touchstart", (ev) => {
        if (ev.touches.length !== 2) return;
        const a = ev.touches[0], b = ev.touches[1];
        pinch = { d0: Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY),
                  z0: (window.APP.editor.gridZoom || 1) };
      }, { passive: true });
      rootEl.addEventListener("touchmove", (ev) => {
        if (!pinch || ev.touches.length !== 2) return;
        if (ev.cancelable) ev.preventDefault();
        const a = ev.touches[0], b = ev.touches[1];
        const d = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
        let z = pinch.z0 * (d / pinch.d0);
        z = Math.max(0.6, Math.min(2.2, z));
        window.APP.editor.gridZoom = z;
        const g = rootEl.querySelector(".chrx-grid");
        if (g) g.style.setProperty("--chrx-grid-zoom", z.toFixed(3));
      }, { passive: false });
      rootEl.addEventListener("touchend", (ev) => { if (!ev.touches || ev.touches.length < 2) pinch = null; }, { passive: true });
      rootEl._chrxWired = true;
    }
  }

  function onMouseOver(ev) {
    const vk = ev.target.closest(".chrx-vkarta");
    if (vk && vk.dataset.lessonId) {
      setPasteAnchor(vk.closest(".chrx-slot"));
      // While a card is in hand: show hover-target info as a tip inside the
      // inspector (Classic-style: bottom-left detail panel updates on hover).
      if (document.body.classList.contains("chrx-card-in-hand")) {
        showHoverTip(vk.dataset.lessonId, {
          day: parseInt(vk.dataset.day, 10),
          period: parseInt(vk.dataset.period, 10),
          classroomId: vk.dataset.classroomId || undefined,
          source: "target",
        });
        return;
      }
      showCardPanel(vk.dataset.lessonId, {
        day: parseInt(vk.dataset.day, 10),
        period: parseInt(vk.dataset.period, 10),
        classroomId: vk.dataset.classroomId || undefined,
        source: "placed",
        halo: vk.dataset.halo || "",
      });
      return;
    }
    const slot = ev.target.closest(".chrx-slot");
    if (slot) setPasteAnchor(slot);
    const label = ev.target.closest(".chrx-rowlabel");
    if (!label) return;
    const row = label.closest(".chrx-row");
    if (!row) return;
    const entityId = row.dataset.row;
    if (!entityId || entityId === "head") return;
    const perspective = window.APP.editor.perspective || "class";
    if (window.FocusMode && typeof window.FocusMode.enter === "function") {
      window.FocusMode.enter(perspective, entityId, true);
    }
  }

  // Classic-style hover tip: updates a dedicated panel inside the inspector
  // when hovering over any card, showing full subject·class·teacher·room detail.
  let hoverTipTimer = null;
  function showHoverTip(lessonId, opts) {
    const S = window.APP && window.APP.school;
    const L = S && S._idx ? S._idx.lessonById[lessonId] : null;
    if (!L) return;
    const host = document.getElementById("editor-inspector-root");
    if (!host) return;
    const subject = S._idx.subjectById[L.subjectId];
    const subjectAbbr = subject ? (subject.abbr || subject.name) : "?";
    const subjectFull = subject ? subject.name : "?";
    const classNames = (L.classIds || []).map(id => S._idx.classById[id]).filter(Boolean).map(c => c.name || c.id).join(", ");
    const teacherNames = (L.teacherIds || []).map(id => S._idx.teacherById[id]).filter(Boolean).map(t => t.name || t.abbr).join(", ");
    const roomId = (opts && opts.classroomId) ? opts.classroomId : L.preferredRoomId;
    const room = roomId ? S._idx.classroomById[roomId] : null;
    const slotLabel = (opts && Number.isFinite(opts.day) && Number.isFinite(opts.period))
      ? `${DAY_LABELS_EN[opts.day] || ("D" + opts.day)} · P${opts.period}`
      : "";
    const hue = subjectHueForId(L.subjectId, subject);
    let tip = document.getElementById("chrx-hover-tip");
    if (!tip) {
      tip = document.createElement("div");
      tip.id = "chrx-hover-tip";
      tip.className = "chrx-hover-tip";
    }
    tip.style.setProperty("--chrx-tip-hue", hue);
    tip.innerHTML = `
      <div class="chrx-hover-tip__subject">
        <span class="chrx-hover-tip__dot"></span>
        <span class="chrx-hover-tip__subj-abbr">${esc(subjectAbbr)}</span>
        ${subjectAbbr !== subjectFull ? `<span class="chrx-hover-tip__subj-full">· ${esc(subjectFull)}</span>` : ""}
      </div>
      <div class="chrx-hover-tip__rows">
        ${classNames ? `<div class="chrx-hover-tip__row"><span class="chrx-hover-tip__label">Class</span><span class="chrx-hover-tip__value">${esc(classNames)}</span></div>` : ""}
        ${teacherNames ? `<div class="chrx-hover-tip__row"><span class="chrx-hover-tip__label">Teacher</span><span class="chrx-hover-tip__value">${esc(teacherNames)}</span></div>` : ""}
        ${room ? `<div class="chrx-hover-tip__row"><span class="chrx-hover-tip__label">Room</span><span class="chrx-hover-tip__value">${esc(room.name)}</span></div>` : ""}
        ${slotLabel ? `<div class="chrx-hover-tip__row"><span class="chrx-hover-tip__label">Slot</span><span class="chrx-hover-tip__value">${esc(slotLabel)}</span></div>` : ""}
      </div>
    `;
    if (tip.parentNode !== host) host.appendChild(tip);
  }

  function hideHoverTip() {
    const tip = document.getElementById("chrx-hover-tip");
    if (tip && tip.parentNode) tip.parentNode.removeChild(tip);
  }

  function subjectHueForId(subjectId, subject) {
    const HUE = { MA:220, MAT:220, MATH:220, MATHS:220, EN:12, ENG:12, ENGL:12, HI:32, HIN:32,
      HINDI:32, SC:150, SCI:150, SS:50, SST:50, SOC:50, MU:285, MUS:285, AR:330, ART:330,
      PE:110, PT:110, PED:110, SP:110, IT:250, CS:250, COMP:250, LIB:200,
      EVS:130, HINDI:32, DRAW:300 };
    const k = (subject ? (subject.abbr || subject.name || "") : "").toUpperCase().replace(/[^A-Z]/g, "");
    if (HUE[k] != null) return HUE[k];
    let h = 0;
    for (let i = 0; i < k.length; i++) h = (h * 31 + k.charCodeAt(i)) & 0xffff;
    return h % 360;
  }

  function onFocusIn(ev) {
    const vk = ev.target.closest(".chrx-vkarta");
    const slot = ev.target.closest(".chrx-slot");
    if (slot) setPasteAnchor(slot);
    if (vk && vk.dataset.lessonId) {
      showCardPanel(vk.dataset.lessonId, {
        day: parseInt(vk.dataset.day, 10),
        period: parseInt(vk.dataset.period, 10),
        classroomId: vk.dataset.classroomId || undefined,
        source: "placed",
        halo: vk.dataset.halo || "",
      });
    }
  }

  function onMouseOut(ev) {
    // Hide hover tip when mouse leaves a card (in normal, non-carry mode)
    if (!document.body.classList.contains("chrx-card-in-hand")) {
      const vk = ev.target.closest(".chrx-vkarta");
      if (vk) {
        hideHoverTip();
        return;
      }
    }
    // Also hide if leaving the target while carrying
    if (document.body.classList.contains("chrx-card-in-hand")) {
      const vk = ev.target.closest(".chrx-vkarta");
      if (vk) hideHoverTip();
    }
    const label = ev.target.closest(".chrx-rowlabel");
    if (!label) return;
    if (window.FocusMode && typeof window.FocusMode.exit === "function") {
      window.FocusMode.exit();
    }
  }

  function onRootClick(ev) {
    const skipBtn = ev.target.closest("[data-skip-to-grid]");
    if (skipBtn) {
      ev.preventDefault();
      focusGridFirst(skipBtn.closest(".chrx-editor"));
      return;
    }
    const selectionAction = ev.target.closest("[data-selection-action]");
    if (selectionAction) {
      ev.preventDefault();
      ev.stopPropagation();
      const action = selectionAction.dataset.selectionAction;
      if (action === "move-day") {
        bulkSelectionAction(action, Number(selectionAction.dataset.selectionDelta) || 0);
      } else {
        bulkSelectionAction(action);
      }
      return;
    }
    const focusNav = ev.target.closest("[data-focus-nav]");
    if (focusNav) {
      ev.preventDefault();
      const action = focusNav.dataset.focusNav;
      if (action === "overview" || action === "focus") {
        window.APP.editor.viewMode = action;
      } else {
        const S = window.APP.school;
        const perspective = window.APP.editor.perspective || "class";
        const rows = rowsFor(S, perspective);
        const current = resolveFocusRow(rows, perspective);
        const index = Math.max(0, rows.findIndex(row => row.key === current.key));
        const direction = action === "prev" ? -1 : 1;
        const next = rows[(index + direction + rows.length) % rows.length];
        if (next) window.APP.editor.focusRowByPerspective[perspective] = next.key;
      }
      // Announce the mode change so the toolbar can reflect what now applies —
      // the zoom control is inert in Focus view and must say so rather than
      // appearing to work (its old silent no-op was a reported confusion).
      document.dispatchEvent(new CustomEvent("editor:view-mode", {
        detail: { viewMode: window.APP.editor.viewMode },
      }));
      render(focusNav.closest(".chrx-editor"));
      return;
    }
    const classRailItem = ev.target.closest(".chrx-class-rail__item");
    if (classRailItem) {
      ev.preventDefault();
      const classId = classRailItem.dataset.classId;
      if (!classId) return;
      const count = parseInt(classRailItem.dataset.unplacedCount, 10) || 0;

      // 1. Select its timetable
      const perspective = window.APP.editor.perspective || "class";
      window.APP.editor = window.APP.editor || {};
      window.APP.editor.focusRowByPerspective = window.APP.editor.focusRowByPerspective || {};
      window.APP.editor.focusRowByPerspective[perspective] = classId;

      // 2. Scopes pending lessons to that class using documented event/API
      window.APP.editor.selectedClassId = classId;
      const pend = document.querySelector(".chrx-pending-strip");
      if (pend && window.PendingStrip && window.PendingStrip.render) {
        window.PendingStrip.render(pend);
      }

      document.dispatchEvent(new CustomEvent("editor:scope-class", {
        detail: { classId, unplacedCount: count }
      }));

      // 3. If counted class (>0 unplaced), request the curtain open
      if (count > 0) {
        document.dispatchEvent(new CustomEvent("curtain:open", {
          detail: { classId, unplacedCount: count, state: "peek", source: "class-rail" }
        }));
        document.dispatchEvent(new CustomEvent("editor:curtain-request", {
          detail: { classId, unplacedCount: count, state: "peek", source: "class-rail" }
        }));
        if (window.Curtain) {
          if (typeof window.Curtain.open === "function") window.Curtain.open({ classId });
          else if (typeof window.Curtain.requestState === "function") window.Curtain.requestState("peek");
          else if (typeof window.Curtain.setState === "function") window.Curtain.setState("peek");
        }
        window.APP.editor.curtainState = "peek";
      }

      render(classRailItem.closest(".chrx-editor"));
      return;
    }

    const tool = ev.target.closest("[data-editor-tool]");
    if (tool) {
      ev.preventDefault();
      handleEditorTool(tool.dataset.editorTool, tool.closest(".chrx-editor"));
      return;
    }
    const tab = ev.target.closest(".chrx-day-tab");
    if (tab) {
      window.APP.day = parseInt(tab.dataset.day, 10) || 0;
      render(tab.closest(".chrx-editor"));
      return;
    }
    const label = ev.target.closest(".chrx-rowlabel");
    if (!label) return;
    const row = label.closest(".chrx-row");
    const rowKey = row && row.dataset.row;
    if (!rowKey || rowKey === "head") return;
    if ((window.APP.editor.perspective || "class") !== "class") return;
    window.APP.editor.selectedClassId = window.APP.editor.selectedClassId === rowKey ? null : rowKey;
    render(label.closest(".chrx-editor"));
    const pend = document.querySelector(".chrx-pending-strip");
    if (pend && window.PendingStrip && window.PendingStrip.render) window.PendingStrip.render(pend);
  }

  function onRootChange(ev) {
    const select = ev.target.closest("[data-focus-entity]");
    if (select) {
      const perspective = window.APP.editor.perspective || "class";
      window.APP.editor.focusRowByPerspective[perspective] = select.value;
      if (perspective === "class") {
        window.APP.editor.selectedClassId = select.value;
      }
      render(select.closest(".chrx-editor"));
      return;
    }
    const studentSearch = ev.target.closest("[data-focus-student-search]");
    if (studentSearch) {
      const val = studentSearch.value.trim().toLowerCase();
      const S = window.APP && window.APP.school;
      if (!S) return;
      const allRows = rowsFor(S, "student");
      const match = allRows.find(r => r.label.toLowerCase() === val || r.key.toLowerCase() === val) ||
                    allRows.find(r => r.label.toLowerCase().startsWith(val));
      if (match) {
        window.APP.editor.focusRowByPerspective["student"] = match.key;
        render(studentSearch.closest(".chrx-editor"));
      }
    }
  }

  function onRootInput(ev) {
    const filterInput = ev.target.closest("[data-student-filter]");
    if (filterInput) {
      const q = filterInput.value.toLowerCase().trim();
      const host = filterInput.closest(".chrx-editor");
      if (host) {
        host.querySelectorAll(".chrx-student-rail .chrx-class-rail__item").forEach(item => {
          const text = (item.textContent || "").toLowerCase();
          item.style.display = (!q || text.includes(q)) ? "" : "none";
        });
      }
      return;
    }
    const studentSearch = ev.target.closest("[data-focus-student-search]");
    if (studentSearch) {
      const val = studentSearch.value.trim().toLowerCase();
      const S = window.APP && window.APP.school;
      if (!S) return;
      const allRows = rowsFor(S, "student");
      const match = allRows.find(r => r.label.toLowerCase() === val || r.key.toLowerCase() === val) ||
                    allRows.find(r => r.label.toLowerCase().startsWith(val));
      if (match) {
        window.APP.editor.focusRowByPerspective["student"] = match.key;
        render(studentSearch.closest(".chrx-editor"));
      }
    }
  }

  function handleEditorTool(kind, host) {
    window.APP.editor = window.APP.editor || {};
    // A card held in hand is bound to the current perspective's row layout.
    // Releasing it before a perspective/colour/zoom change avoids a lingering
    // drag ghost and a validity heatmap painted against the wrong rows after the
    // grid is rebuilt. (BUG_REPORT_2026-06-13 S0.2.)
    if ((kind === "perspective" || kind === "color" || kind === "density" || kind === "zoom") &&
        window.APP.editor.cardInHand &&
        window.CardInHand && typeof window.CardInHand.cancel === "function") {
      window.CardInHand.cancel();
    }
    if (kind === "perspective") {
      const cur = window.APP.editor.perspective || "class";
      const next = PERSPECTIVES[(PERSPECTIVES.indexOf(cur) + 1) % PERSPECTIVES.length];
      window.APP.editor.perspective = next;
      syncExternalButton("editor-perspective", PERSPECTIVE_LABEL[next]);
    } else if (kind === "color") {
      const cur = window.APP.editor.colorBy || "subject";
      const next = COLOR_AXES[(COLOR_AXES.indexOf(cur) + 1) % COLOR_AXES.length];
      window.APP.editor.colorBy = next;
      try { localStorage.setItem("chronexa.editor.colorBy", next); } catch (_e) {}
      syncExternalButton("editor-color-by", COLOR_LABEL[next]);
    } else if (kind === "density" || kind === "zoom") {
      const cur = currentZoom();
      setZoom(ZOOM_LEVELS[(ZOOM_LEVELS.indexOf(cur) + 1) % ZOOM_LEVELS.length]);
      syncExternalButton("editor-density", ZOOM_LABELS[currentZoom()]);
    } else if (kind === "open-supervisions") {
      // The Supervision perspective's empty state opens the existing entity
      // dialog — the grid itself stays read-only.
      window.dispatchEvent(new CustomEvent("app:open-entity", { detail: { kind: "supervisions" } }));
    }
    if (host) render(host);
    const pend = document.querySelector(".chrx-pending-strip");
    if (pend && window.PendingStrip && window.PendingStrip.render) window.PendingStrip.render(pend);
  }

  function syncExternalButton(id, text) {
    const btn = document.getElementById(id);
    if (btn) btn.textContent = text;
  }

  function updateClassPanel(S) {
    const existing = document.getElementById("chrx-class-panel");
    const selectedId = window.APP && window.APP.editor && window.APP.editor.selectedClassId;
    const cls = selectedId && S && S._idx ? S._idx.classById[selectedId] : null;
    if (!cls) {
      if (existing) existing.remove();
      return;
    }
    const stats = classStats(S, selectedId);
    const panel = existing || document.createElement("aside");
    panel.id = "chrx-class-panel";
    panel.className = "chrx-class-panel";
    panel.innerHTML = `
      <div class="chrx-class-panel__eyebrow">Selected class</div>
      <div class="chrx-class-panel__title">${esc(cls.name || cls.id)}</div>
      <div class="chrx-class-panel__stats">
        <div><strong>${stats.placed}</strong><span>placed</span></div>
        <div><strong>${stats.pending}</strong><span>pending</span></div>
        <div><strong>${stats.conflicts}</strong><span>conflicts</span></div>
      </div>
      <div class="chrx-class-panel__meta">${esc(stats.teachers || "No teachers assigned")}</div>
      <div class="chrx-class-panel__actions">
        <button type="button" data-act="clear">Show all</button>
        <button type="button" data-act="lesson-grid">Lesson grid</button>
      </div>
    `;
    panel.querySelector('[data-act="clear"]').onclick = () => {
      window.APP.editor.selectedClassId = null;
      const host = document.querySelector(".chrx-editor");
      if (host) render(host);
      const pend = document.querySelector(".chrx-pending-strip");
      if (pend && window.PendingStrip && window.PendingStrip.render) window.PendingStrip.render(pend);
    };
    panel.querySelector('[data-act="lesson-grid"]').onclick = () => {
      if (window.LessonsGridMatrix && window.LessonsGridMatrix.open) window.LessonsGridMatrix.open(S);
    };
    attachInspectorPanel(panel);
  }

  function showCardPanel(lessonId, opts) {
    const S = window.APP && window.APP.school;
    const L = S && S._idx ? S._idx.lessonById[lessonId] : null;
    if (!L) return;
    const subject = S._idx.subjectById[L.subjectId];
    const subjectName = subject ? (subject.name || subject.abbr) : "Unknown";
    const classNames = (L.classIds || []).map(id => S._idx.classById[id]).filter(Boolean).map(c => c.name || c.id).join(", ");
    const teacherNames = (L.teacherIds || []).map(id => S._idx.teacherById[id]).filter(Boolean).map(t => t.abbr || t.name).join(", ");
    const roomId = opts && opts.classroomId ? opts.classroomId : L.preferredRoomId;
   const room = roomId ? S._idx.classroomById[roomId] : null;
   const len = L.lessonLength || (L.isLabDouble ? 2 : 1);
   const ppw = Math.ceil(L.periodsPerWeek || 0);
   const need = ppw > 0 ? Math.max(1, Math.round(ppw / len)) : 0;
   const placed = (S.cards || []).filter(c => c.lessonId === L.id).length;
    const position = opts && Number.isFinite(opts.day) && Number.isFinite(opts.period)
      ? `${DAY_LABELS_EN[opts.day] || ("D" + opts.day)} P${opts.period}`
      : "Unplaced";
    // A placed card is judged by the validator halo it already carries —
    // re-classifying its own slot would flag it as colliding with itself.
    const status = opts && opts.source === "placed"
      ? (opts.halo === "red"   ? { state: "red",   text: "Hard conflict" }
       : opts.halo === "amber" ? { state: "amber", text: "Soft warning" }
       :                         { state: "green", text: "On the timetable" })
      : placementStatus(L.id, opts);
    const panel = document.getElementById("chrx-card-panel") || document.createElement("aside");
    panel.id = "chrx-card-panel";
    panel.className = "chrx-card-panel";
    panel.style.setProperty("--chrx-panel-hue", subjectHueForId(L.subjectId, subject));
    const row = (ic, label, value) =>
      `<div class="chrx-card-panel__row">${icon(ic, 15)}<dt>${label}</dt><dd title="${esc(value || "")}">${esc(value || "—")}</dd></div>`;
    panel.innerHTML = `
      <div class="chrx-card-panel__eyebrow">${opts && opts.source === "pending" ? "Unplaced lesson" : "Lesson"}</div>
      <div class="chrx-card-panel__title"><span class="chrx-card-panel__dot"></span><span>${esc(subjectName)}</span></div>
      <dl class="chrx-card-panel__rows">
        ${row("class", "Class", classNames)}
        ${row("teacher", "Teacher", teacherNames)}
        ${row("room", "Room", room ? room.name : "")}
        ${row("calendar", "Slot", position)}
      </dl>
      <div class="chrx-card-panel__progress"><span style="width:${Math.min(100, need ? placed / need * 100 : 0)}%"></span></div>
      <div class="chrx-card-panel__foot"><span>${placed} of ${need || 0} placed</span><span class="chrx-card-panel__pill">${esc(status.text)}</span></div>
    `;
    panel.dataset.state = status.state;
    attachInspectorPanel(panel);
  }

  function attachInspectorPanel(panel) {
    const host = document.getElementById("editor-inspector-root");
    if (host && panel.parentNode !== host) host.appendChild(panel);
    else if (!host && !panel.parentNode) document.body.appendChild(panel);
  }

  function placementStatus(lessonId, opts) {
    if (!opts || !Number.isFinite(opts.day) || !Number.isFinite(opts.period) || !window.Placement) {
      return { state: "idle", text: "ready to place" };
    }
    try {
      const v = window.Placement.classify(lessonId, opts.day, opts.period, opts.classroomId);
      if (v.validity === "red") return { state: "red", text: (v.reasons || ["hard conflict"])[0] };
      if (v.validity === "amber") return { state: "amber", text: (v.reasons || ["soft warning"])[0] };
      return { state: "green", text: "clean slot" };
    } catch (_e) {
      return { state: "idle", text: "ready to place" };
    }
  }

  function classStats(S, classId) {
    let pending = 0, placed = 0, conflicts = 0;
    const teacherNames = new Set();
    const filter = currentViewFilter();
   for (const L of (S.lessons || [])) {
     if (!(L.classIds || []).includes(classId)) continue;
     if (!lessonMatchesFilter(L, filter, S)) continue;
     const len = L.lessonLength || (L.isLabDouble ? 2 : 1);
     const ppw = Math.ceil(L.periodsPerWeek || 0);
     const need = ppw > 0 ? Math.max(1, Math.round(ppw / len)) : 0;
     const have = (S.cards || []).filter(c => c.lessonId === L.id).length;
      pending += Math.max(0, need - have);
      placed += have;
      (L.teacherIds || []).forEach(tid => {
        const t = S._idx.teacherById[tid];
        if (t) teacherNames.add(t.abbr || t.name);
      });
    }
    const bySlot = Object.create(null);
    for (const c of (S.cards || [])) {
      const L = S._idx.lessonById[c.lessonId];
      if (!L || !(L.classIds || []).includes(classId)) continue;
      if (!lessonMatchesFilter(L, filter, S)) continue;
      const key = c.day + "_" + c.period;
      bySlot[key] = (bySlot[key] || 0) + 1;
    }
    conflicts = Object.values(bySlot).filter(n => n > 1).length;
    return {
      pending,
      placed,
      conflicts,
      teachers: Array.from(teacherNames).slice(0, 6).join(", "),
    };
  }

  function handleCardClick(vk) {
    if (window.APP?.editor?.perspective === "student" || vk.classList.contains("locked")) return;
    const cardId = vk.dataset.cardId;
    const lessonId = vk.dataset.lessonId;
    const day = parseInt(vk.dataset.day, 10);
    const period = parseInt(vk.dataset.period, 10);
    const originClassroomId = vk.dataset.classroomId || undefined;
    const rowKey = vk.closest(".chrx-row")?.dataset.row;
    
    const held = window.APP.editor.cardInHand;
    if (held) {
      if (held.cardId === cardId) {
        // Clicked the selected card again: Deselect
        window.CardInHand.cancel();
        return;
      }
      window.CardInHand.cancel();
    }
    
    // Keep the picked card in the model until the user completes an action.
    // This makes pickup itself non-mutating: Delete, place, move, and swap can
    // each be recorded as exactly one APP.mutate transaction, while Escape is
    // a true no-op. CardInHand filters this retained source from drop targets.
    const cardsBefore = snapshotCards();
    window.APP.editor.cardInHand = { cardId, lessonId, originDay: day, originPeriod: period, originClassroomId, rowKey, sourceRetained: true, mode: "click" };
    syncCardInHandClass();
    dispatch("editor:pickup", { cardId, lessonId, day, period, originClassroomId, rowKey, sourceRetained: true, mode: "click", cardsBefore });
  }

  function startDragPickup(vk, startX, startY, pointerId, grabRatioX, grabRatioY) {
    if (window.APP?.editor?.perspective === "student") return;
    const cardId = vk.dataset.cardId;
    const lessonId = vk.dataset.lessonId;
    const day = parseInt(vk.dataset.day, 10);
    const period = parseInt(vk.dataset.period, 10);
    const originClassroomId = vk.dataset.classroomId || undefined;
    const blockLen = parseInt(vk.dataset.blockLen, 10) || 1;   // double-period block moves as one

    const held = window.APP.editor.cardInHand;
    if (held) {
      if (!held.sourceRetained) placeCardOnSchool(held.lessonId, held.originDay, held.originPeriod);
      window.APP.editor.cardInHand = null;
      dispatch("editor:restore", { cardId: held.cardId, lessonId: held.lessonId,
        day: held.originDay, period: held.originPeriod, reason: "second-pickup" });
    }

    // Keep the source card in place as an origin placeholder. The model is
    // mutated only when the drop commits, so cancel is instant and lossless.
    const cardsBefore = snapshotCards();
    vk.classList.add("chrx-vk-source");
    vk.setAttribute("aria-grabbed", "true");
    window.APP.editor.cardInHand = { cardId, lessonId, originDay: day, originPeriod: period, originClassroomId, blockLen, sourceRetained: true, mode: "drag" };
    syncCardInHandClass();
    dispatch("editor:pickup", { cardId, lessonId, day, period, originClassroomId, blockLen,
      sourceX: startX, sourceY: startY, pointerId, grabRatioX, grabRatioY,
      sourceRetained: true, mode: "drag", cardsBefore });
    if (held) {
      const host = vk.closest(".chrx-editor");
      if (host) render(host);
    }
  }

  // Plan C: touch drag. A long-press (≈320ms held still) on a card picks it up
  // for dragging; a quick tap selects it; a finger that moves first is a scroll
  // and is left alone. Once picked up, CardInHand's touchmove/touchend handlers
  // take over (see card_in_hand.js).
  function onTouchStart(ev) {
    // Click-to-place mode: a tap on a highlighted slot commits, like a click.
    if (window.APP.editor.cardInHand && window.APP.editor.cardInHand.mode === "click") return;
    const vk = ev.target.closest(".chrx-vkarta");
    if (!vk || window.APP?.editor?.perspective === "student" || vk.classList.contains("locked")) return;
    const t = ev.touches[0]; if (!t) return;
    const sx = t.clientX, sy = t.clientY;
    let moved = false, fired = false;
    const lp = setTimeout(() => {
      if (moved) return;
      fired = true;
      cleanupTS();
      if (navigator.vibrate) { try { navigator.vibrate(15); } catch (_) {} }   // haptic
      startDragPickup(vk, sx, sy);
    }, 320);
    function tm(e) {
      const tt = e.touches[0]; if (!tt) return;
      if (Math.hypot(tt.clientX - sx, tt.clientY - sy) > 10) { moved = true; clearTimeout(lp); cleanupTS(); }
    }
    function te() { clearTimeout(lp); cleanupTS(); if (!fired && !moved) handleCardClick(vk); }
    function cleanupTS() {
      document.removeEventListener("touchmove", tm, true);
      document.removeEventListener("touchend", te, true);
      document.removeEventListener("touchcancel", te, true);
    }
    document.addEventListener("touchmove", tm, true);
    document.addEventListener("touchend", te, true);
    document.addEventListener("touchcancel", te, true);
  }

  // Plan C: on a phone (single-day view) a horizontal swipe across the grid
  // changes the active day. Desktop shows all days, so it's gated to ≤767px and
  // never fires while a card is being carried/picked up.
  function onSwipeStart(ev) {
    if (!isMobileViewport()) return;
    if (window.APP.editor.cardInHand) return;
    const t = ev.touches[0]; if (!t) return;
    const sx = t.clientX, sy = t.clientY, t0 = Date.now();
    function end(e) {
      document.removeEventListener("touchend", end, true);
      if (window.APP.editor.cardInHand) return;        // a pickup happened — ignore
      if (Date.now() - t0 > 600) return;               // slow = scroll/hold, not a swipe
      const tt = e.changedTouches && e.changedTouches[0]; if (!tt) return;
      const dx = tt.clientX - sx, dy = tt.clientY - sy;
      if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 2) changeDay(dx < 0 ? 1 : -1);
    }
    document.addEventListener("touchend", end, true);
  }
  function changeDay(dir) {
    const S = window.APP.school; if (!S) return;
    const nd = dayCount(S);
    let d = (window.APP.day || 0) + dir;
    d = Math.max(0, Math.min(nd - 1, d));
    if (d === (window.APP.day || 0)) return;
    window.APP.day = d;
    const host = document.querySelector(".chrx-editor");
    if (host) render(host);
  }

  /* ── Keyboard navigation & roving tabindex (B10) ────────────────────────── */
  let activeRovingCardId = null;

  function initRovingTabindex(rootEl) {
    if (!rootEl) return;
    const cards = Array.from(rootEl.querySelectorAll(".chrx-vkarta"));
    const emptySlots = Array.from(rootEl.querySelectorAll(".chrx-slot.empty:not(.out-of-bell)"));
    for (const slot of emptySlots) {
      if (slot.getAttribute("tabindex") !== "0") slot.setAttribute("tabindex", "-1");
    }
    if (cards.length > 0) {
      let targetCard = null;
      if (activeRovingCardId) {
        targetCard = cards.find(c => c.dataset.cardId === activeRovingCardId);
      }
      if (!targetCard) targetCard = cards[0];
      for (const card of cards) {
        card.setAttribute("tabindex", card === targetCard ? "0" : "-1");
      }
    } else if (emptySlots.length > 0) {
      emptySlots[0].setAttribute("tabindex", "0");
    }
  }

  function updateRovingTabindex(rootEl, activeEl) {
    if (!rootEl || !activeEl) return;
    const focusables = rootEl.querySelectorAll(".chrx-vkarta, .chrx-slot");
    for (const f of focusables) {
      if (f === activeEl) {
        f.setAttribute("tabindex", "0");
      } else if (f.getAttribute("tabindex") === "0") {
        f.setAttribute("tabindex", "-1");
      }
    }
  }

  function focusTarget(el) {
    if (!el) return;
    const root = el.closest(".chrx-editor") || document.getElementById("editor-root");
    if (root) updateRovingTabindex(root, el);
    const card = el.classList.contains("chrx-vkarta") ? el : el.querySelector(".chrx-vkarta");
    if (card && card.dataset.cardId) activeRovingCardId = card.dataset.cardId;
    el.focus();
  }

  function focusGridFirst(rootEl) {
    if (!rootEl) return;
    const card = rootEl.querySelector(".chrx-vkarta");
    const slot = rootEl.querySelector(".chrx-slot:not(.out-of-bell)");
    focusTarget(card || slot);
  }

  function handleArrowNav(rootEl, currentSlot, currentCard, key) {
    const isFocus = window.APP?.editor?.viewMode === "focus";
    const isMobile = isMobileViewport(rootEl);
    const inHand = !!window.APP?.editor?.cardInHand;
    const slot = currentSlot || currentCard?.closest(".chrx-slot");

    if (isFocus && slot) {
      const board = rootEl.querySelector(".chrx-focus-board") || rootEl;
      const day = parseInt(slot.dataset.day, 10);
      const period = parseInt(slot.dataset.period, 10);
      const S = window.APP?.school;
      const numDays = dayCount(S);
      const periods = displayPeriods(S);
      const pIndices = periods.map(p => p.index | 0);
      const pIdx = pIndices.indexOf(period);

      if (isMobile) {
        let nextPIdx = pIdx;
        if (key === "ArrowDown" || key === "ArrowRight") nextPIdx = Math.min(pIndices.length - 1, pIdx + 1);
        if (key === "ArrowUp" || key === "ArrowLeft") nextPIdx = Math.max(0, pIdx - 1);
        const targetSlot = board.querySelector(`.chrx-slot[data-day="${day}"][data-period="${pIndices[nextPIdx]}"]`);
        if (targetSlot) {
          const targetCard = targetSlot.querySelector(".chrx-vkarta");
          focusTarget(inHand ? targetSlot : (targetCard || targetSlot));
          return;
        }
      } else {
        let nextDay = day;
        let nextPIdx = pIdx;
        if (key === "ArrowRight") {
          if (nextDay + 1 < numDays) nextDay++;
          else if (nextPIdx + 1 < pIndices.length) { nextDay = 0; nextPIdx++; }
        } else if (key === "ArrowLeft") {
          if (nextDay - 1 >= 0) nextDay--;
          else if (nextPIdx - 1 >= 0) { nextDay = numDays - 1; nextPIdx--; }
        } else if (key === "ArrowDown") {
          if (nextPIdx + 1 < pIndices.length) nextPIdx++;
        } else if (key === "ArrowUp") {
          if (nextPIdx - 1 >= 0) nextPIdx--;
        }
        const targetSlot = board.querySelector(`.chrx-slot[data-day="${nextDay}"][data-period="${pIndices[nextPIdx]}"]`);
        if (targetSlot) {
          const targetCard = targetSlot.querySelector(".chrx-vkarta");
          focusTarget(inHand ? targetSlot : (targetCard || targetSlot));
          return;
        }
      }
    } else if (!isFocus && slot) {
      const row = slot.closest(".chrx-row");
      const allRows = Array.from(rootEl.querySelectorAll(".chrx-row[data-row]:not([data-row='head'])"));
      const rowIdx = allRows.indexOf(row);
      const day = parseInt(slot.dataset.day, 10);
      const period = parseInt(slot.dataset.period, 10);
      const S = window.APP?.school;
      const numDays = dayCount(S);
      const periods = displayPeriods(S);
      const pIndices = periods.map(p => p.index | 0);
      const pIdx = pIndices.indexOf(period);

      let nextDay = day;
      let nextPIdx = pIdx;
      let nextRowIdx = rowIdx;
      if (key === "ArrowRight") {
        if (nextPIdx + 1 < pIndices.length) nextPIdx++;
        else if (nextDay + 1 < numDays) { nextDay++; nextPIdx = 0; }
      } else if (key === "ArrowLeft") {
        if (nextPIdx - 1 >= 0) nextPIdx--;
        else if (nextDay - 1 >= 0) { nextDay--; nextPIdx = pIndices.length - 1; }
      } else if (key === "ArrowDown") {
        if (nextRowIdx + 1 < allRows.length) nextRowIdx++;
      } else if (key === "ArrowUp") {
        if (nextRowIdx - 1 >= 0) nextRowIdx--;
      }
      const targetRow = allRows[nextRowIdx];
      const targetSlot = targetRow?.querySelector(`.chrx-slot[data-day="${nextDay}"][data-period="${pIndices[nextPIdx]}"]`);
      if (targetSlot) {
        const targetCard = targetSlot.querySelector(".chrx-vkarta");
        focusTarget(inHand ? targetSlot : (targetCard || targetSlot));
        return;
      }
    }

    if (inHand) {
      const slots = Array.from(rootEl.querySelectorAll(".chrx-slot:not(.out-of-bell)"));
      if (slots.length) {
        const idx = slot ? slots.indexOf(slot) : -1;
        const dir = (key === "ArrowDown" || key === "ArrowRight") ? 1 : -1;
        const nextIdx = (idx + dir + slots.length) % slots.length;
        focusTarget(slots[nextIdx]);
        return;
      }
    }

    const cards = Array.from(rootEl.querySelectorAll(".chrx-vkarta"));
    if (cards.length) {
      const idx = currentCard ? cards.indexOf(currentCard) : -1;
      const dir = (key === "ArrowDown" || key === "ArrowRight") ? 1 : -1;
      const nextIdx = (idx + dir + cards.length) % cards.length;
      focusTarget(cards[nextIdx]);
    }
  }

  function onGridKeyDown(ev) {
    const key = ev.key;
    const rootEl = ev.currentTarget;
    const skipBtn = ev.target.closest("[data-skip-to-grid]");
    if (skipBtn && (key === "Enter" || key === " ")) {
      ev.preventDefault();
      focusGridFirst(rootEl);
      return;
    }
    const active = document.activeElement;
    const card = active?.closest?.(".chrx-vkarta");
    const slot = active?.closest?.(".chrx-slot");
    if (!card && !slot) return;

    const modified = ev.metaKey || ev.ctrlKey;
    if (modified && !ev.altKey && (key === "c" || key === "C")) {
      if (window.APP.editor.selectedCardIds?.length) {
        ev.preventDefault();
        copySelection();
      }
      return;
    }
    if (modified && !ev.altKey && (key === "v" || key === "V")) {
      if (window.APP.editor.cardClipboard) {
        ev.preventDefault();
        pasteSelection();
      }
      return;
    }

    if (key === "Escape" && !window.APP.editor.cardInHand) {
      if (window.APP.editor.selectedCardIds?.length) {
        ev.preventDefault();
        clearSelection(rootEl);
      }
      return;
    }

    if (key === " " && !window.APP.editor.cardInHand && card) {
      ev.preventDefault();
      selectCardElement(card, { toggle: true });
      return;
    }

    if ((key === "Enter" || key === " ") && card && !window.APP.editor.cardInHand) {
      if (window.APP?.editor?.perspective === "student" || card.classList.contains("locked")) return;
      ev.preventDefault();
      const rect = card.getBoundingClientRect();
      startDragPickup(card, rect.left + rect.width / 2, rect.top + rect.height / 2);
      const parentSlot = card.closest(".chrx-slot");
      if (parentSlot) focusTarget(parentSlot);
      return;
    }

    if (key === "Enter" && window.APP.editor.cardInHand) {
      if (card && slot && active !== slot) {
        slot.focus();
      }
      return;
    }

    if (key === "ArrowDown" || key === "ArrowUp" || key === "ArrowRight" || key === "ArrowLeft") {
      ev.preventDefault();
      const priorCard = card;
      if (ev.shiftKey && priorCard) {
        if (!window.APP.editor.selectionAnchorCardId) {
          window.APP.editor.selectionAnchorCardId = priorCard.dataset.cardId;
        }
      }
      handleArrowNav(rootEl, slot, card, key);
      if (ev.shiftKey && !window.APP.editor.cardInHand) {
        const next = document.activeElement?.closest?.(".chrx-vkarta");
        if (next) selectCardElement(next, { range: true, preserveAnchor: true });
      }
    }
  }

  function wireKeyboardNav(rootEl) {
    rootEl.addEventListener("keydown", onGridKeyDown);
    rootEl.addEventListener("focusin", (ev) => {
      const skipBtn = ev.target.closest("[data-skip-to-grid]");
      if (skipBtn) {
        skipBtn.classList.remove("chrx-sr-only");
        skipBtn.style.top = "8px";
        skipBtn.style.left = "8px";
        return;
      }
      const vk = ev.target.closest(".chrx-vkarta");
      const slot = ev.target.closest(".chrx-slot");
      if (vk) {
        activeRovingCardId = vk.dataset.cardId || null;
        updateRovingTabindex(rootEl, vk);
      } else if (slot) {
        activeRovingCardId = null;
        updateRovingTabindex(rootEl, slot);
      }
    });
    rootEl.addEventListener("focusout", (ev) => {
      const skipBtn = ev.target.closest("[data-skip-to-grid]");
      if (skipBtn) {
        skipBtn.classList.add("chrx-sr-only");
        skipBtn.style.top = "";
        skipBtn.style.left = "";
      }
    });
  }

  function onPointerDown(ev) {
    // Only the primary button drives pickup/place/swap. Right-click must fall
    // through to the context menu — without this guard a right-click on a
    // card PICKED IT UP first, and the menu's "Remove" then early-returned
    // (card already out of school.cards), stranding the card in hand and
    // leaving the pending strip stale (found by the drag-card E2E flow).
    if (ev.button !== 0) return;
    cancelPendingCardClick();
    // If click-to-swap selection is active, intercept clicks on empty or occupied slots
    if (window.APP.editor.cardInHand && window.APP.editor.cardInHand.mode === "click") {
      const slot = ev.target.closest(".chrx-slot");
      if (slot) {
        ev.preventDefault();
        const d = parseInt(slot.dataset.day, 10);
        const p = parseInt(slot.dataset.period, 10);
        
        if (slot.classList.contains("chrx-slot--highlight-place") || slot.classList.contains("chrx-slot--highlight-swap")) {
          const occupants = slot.querySelectorAll(".chrx-vkarta");
          if (occupants.length) {
            // Swap: the picked card takes this slot and the card sitting here
            // moves to the cursor. swap() refuses (and opens the collision
            // menu) if the picked card would be a hard conflict here once the
            // displaced card is removed — e.g. its teacher is busy elsewhere.
            const targetVk = ev.target.closest(".chrx-vkarta");
            window.CardInHand.swap(d, p, slot, targetVk ? targetVk.dataset.lessonId : null);
          } else {
            window.CardInHand.commit(d, p, slot);
          }
          return;
        } else {
          // If they click another card in a different row, cancel selection and select the clicked one instead!
          const targetVk = ev.target.closest(".chrx-vkarta");
          window.CardInHand.cancel();
          if (targetVk && targetVk.dataset.cardId !== window.APP.editor.cardInHand?.cardId) {
            handleCardClick(targetVk);
            return;
          }
        }
      }
    }

    const vk = ev.target.closest(".chrx-vkarta");
    const slot = ev.target.closest(".chrx-slot");
    if (slot) setPasteAnchor(slot);

    // Modifier-click belongs exclusively to multi-select. Keep this before
    // the locked guard so a locked card can be selected for bulk Unlock.
    if (vk && (ev.metaKey || ev.ctrlKey || ev.shiftKey)) {
      ev.preventDefault();
      ev.stopPropagation();
      selectCardElement(vk, {
        range: !!ev.shiftKey,
        toggle: !ev.shiftKey,
      });
      focusTarget(vk);
      return;
    }

    // Dragging from empty grid space draws a marquee. It is scoped to an
    // actual slot so labels, tabs, and the scroll container keep their native
    // interactions.
    if (!vk && slot && slot.classList.contains("empty") &&
        !slot.classList.contains("out-of-bell") && !window.APP.editor.cardInHand) {
      ev.preventDefault();
      ev.stopPropagation();
      marqueeSelection(ev.currentTarget, ev, slot);
      return;
    }

    // Card pickup / Click-to-select duality
    if (vk) {
      if (window.APP?.editor?.perspective === "student" || vk.classList.contains("locked")) return;
      ev.preventDefault();
      
      const startX = ev.clientX;
      const startY = ev.clientY;
      const pointerId = ev.pointerId;
      const pointerOwner = ev.currentTarget;
      const rect = vk.getBoundingClientRect();
      const grabRatioX = rect.width ? (startX - rect.left) / rect.width : 0.5;
      const grabRatioY = rect.height ? (startY - rect.top) / rect.height : 0.5;
      let dragTriggered = false;
      pointerOwner.setPointerCapture?.(pointerId);

      function onPointerMove(moveEv) {
        if (moveEv.pointerId !== pointerId) return;
        if (dragTriggered) return;
        const dx = moveEv.clientX - startX;
        const dy = moveEv.clientY - startY;
        if (Math.hypot(dx, dy) > 5) {
          dragTriggered = true;
          cleanup();
          startDragPickup(vk, moveEv.clientX, moveEv.clientY, pointerId, grabRatioX, grabRatioY);
        }
      }

      function onPointerUp(upEv) {
        if (upEv.pointerId !== pointerId) return;
        cleanup();
        if (!dragTriggered && upEv.type !== "pointercancel") {
          // Keep the card in the DOM long enough for a native dblclick to
          // arrive. The first click otherwise rerenders its source slot before
          // card_double_click.js can resolve the second click's target.
          cancelPendingCardClick();
          pendingCardClickTimer = setTimeout(() => {
            pendingCardClickTimer = null;
            handleCardClick(vk);
          }, 250);
        }
      }

      function cleanup() {
        pointerOwner.releasePointerCapture?.(pointerId);
        document.removeEventListener("pointermove", onPointerMove, true);
        document.removeEventListener("pointerup", onPointerUp, true);
        document.removeEventListener("pointercancel", onPointerUp, true);
      }

      document.addEventListener("pointermove", onPointerMove, true);
      document.addEventListener("pointerup", onPointerUp, true);
      document.addEventListener("pointercancel", onPointerUp, true);
      return;
    }

    // Empty-slot place (only when we have something in hand)
    if (slot && window.APP.editor.cardInHand) {
      ev.preventDefault();
      return;
    }
  }

  function dispatch(name, detail) {
    document.dispatchEvent(new CustomEvent(name, { detail }));
  }

  // S.cards is the single source of truth.
  function removeCardFromSchool(lessonId, day, period) {
    const S = window.APP.school;
    if (!S) return;
    const i = S.cards.findIndex(c => c.lessonId === lessonId && c.day === day && c.period === period);
    if (i !== -1) S.cards.splice(i, 1);
  }

  function placeCardOnSchool(lessonId, day, period) {
    const S = window.APP.school;
    if (!S) return;
    const lesson = S._idx.lessonById[lessonId];
    const classroomId = arguments.length >= 4 ? arguments[3] : (lesson ? lesson.preferredRoomId : undefined);
    // Avoid a duplicate placement on the same {lessonId, day, period}
    if (S.cards.some(c => c.lessonId === lessonId && c.day === day && c.period === period)) return;
    S.cards.push({ lessonId, day, period, classroomId });
  }


  // Subject hue: known short codes match design tokens, else hash.
  const SHORT_HUES = {
    MA: 220, MAT: 220, MATH: 220, MATHS: 220,
    EN: 12,  ENG: 12,  ENGL: 12,
    HI: 32,  HIN: 32,  HINDI: 32,
    SC: 150, SCI: 150, SCIE: 150,
    SS: 50,  SST: 50,  SOC: 50,
    MU: 285, MUS: 285,
    AR: 330, ART: 330,
    PE: 110, PT: 110, PED: 110, SP: 110,
    IT: 250, CS: 250, COMP: 250,
    LIB: 200,
  };
  function subjectHue(subject) {
    if (!subject) return 210;
    const key = (subject.abbr || subject.name || "").toUpperCase().replace(/[^A-Z]/g, "");
    if (SHORT_HUES[key] != null) return SHORT_HUES[key];
    let h = 0;
    for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) & 0xffff;
    return h % 360;
  }

  // Pick the colour of a placed card based on APP.editor.colorBy:
  //   "subject" (default) — use the legacy subject-hue palette
  //   "teacher" — use the first teacher's stored colour, hash-fallback
  //   "class"   — use the first class's stored colour, hash-fallback
  //   "room"    — use the resolved classroom's stored colour, hash-fallback
  // Entity dialogs already write a HEX `color` field on each entity; we
  // parse it to HSL hue when present so it composes with the existing
  // --chrx-card-hue CSS variable used by chrx-vkarta.
  // Diagonal N-colour stripes (one band per teacher) for a co-taught card.
  function teacherStripes(hues) {
    const n = hues.length;
    if (n < 2) return null;
    const step = 100 / n;
    const stops = hues.map((h, i) =>
      `hsl(${h} 70% 47%) ${(i * step).toFixed(2)}% ${((i + 1) * step).toFixed(2)}%`
    ).join(", ");
    return `linear-gradient(135deg, ${stops})`;
  }
  function hashHue(key) {
    if (!key) return 210;
    let h = 0;
    const u = String(key).toUpperCase();
    for (let i = 0; i < u.length; i++) h = (h * 31 + u.charCodeAt(i)) & 0xffff;
    return h % 360;
  }
  function hexHue(hex) {
    if (typeof hex !== "string") return null;
    const m = hex.replace("#", "");
    if (m.length !== 6) return null;
    const r = parseInt(m.slice(0, 2), 16) / 255;
    const g = parseInt(m.slice(2, 4), 16) / 255;
    const b = parseInt(m.slice(4, 6), 16) / 255;
    if ([r, g, b].some(v => Number.isNaN(v))) return null;
    const max = Math.max(r, g, b), min = Math.min(r, g, b), d = max - min;
    if (d === 0) return 210;
    let h;
    if (max === r) h = ((g - b) / d) % 6;
    else if (max === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h *= 60; if (h < 0) h += 360;
    return Math.round(h);
  }
  function cardHue(S, card, lesson, subject) {
    const axis = (window.APP && window.APP.editor && window.APP.editor.colorBy) || "subject";
    if (axis === "subject") return subjectHue(subject);
    if (axis === "teacher") {
      const tid = (lesson && lesson.teacherIds && lesson.teacherIds[0]);
      const t = tid ? S._idx.teacherById[tid] : null;
      return (t && hexHue(t.color)) ?? hashHue(t && (t.abbr || t.name));
    }
    if (axis === "class") {
      const cid = (lesson && lesson.classIds && lesson.classIds[0]);
      const c = cid ? S._idx.classById[cid] : null;
      return (c && hexHue(c.color)) ?? hashHue(c && (c.short || c.name));
    }
    if (axis === "room") {
      const rid = (card && card.classroomId) || (lesson && lesson.preferredRoomId);
      const r = rid ? S._idx.classroomById[rid] : null;
      return (r && hexHue(r.color)) ?? hashHue(r && (r.short || r.name));
    }
    return subjectHue(subject);
  }

  /**
   * Auto-size row-label column width + scale individual labels.
   *
   * 1. Temporarily remove width constraint so we can measure natural text width.
   * 2. Find the widest label (clamped to 32–120 px).
   * 3. Set --chrx-rowlabel-w on the grid so all rows get the same width.
   * 4. Any label still wider than the column gets scaleX() compression.
   */
  function autoFitRowLabels(rootEl) {
    const grid = rootEl.querySelector(".chrx-grid");
    if (!grid) return;
    const mains = grid.querySelectorAll(".chrx-rowlabel-main");
    if (!mains.length) return;

    // Step 1 — reset transforms and temporarily let labels be auto-width
    // so we can measure their natural text width
    for (const m of mains) m.style.transform = "none";
    grid.style.setProperty("--chrx-rowlabel-w", "auto");

    // Step 2 — find the widest label's natural text width
    let maxW = 0;
    for (const m of mains) {
      const w = m.scrollWidth;
      if (w > maxW) maxW = w;
    }

    // Step 3 — compute optimal column width (text + 6px padding), clamped
    const PAD = 8; // 3px padding each side + 2px safety
    const MIN_W = 32;
    const MAX_W = 120;
    const optimalW = Math.min(MAX_W, Math.max(MIN_W, maxW + PAD));
    grid.style.setProperty("--chrx-rowlabel-w", optimalW + "px");

    // Step 4 — scaleX any labels that are wider than the column
    const usable = optimalW - PAD;
    for (const m of mains) {
      const textW = m.scrollWidth;
      if (textW > usable) {
        const scale = usable / textW;
        m.style.transform = "scaleX(" + Math.max(0.5, scale).toFixed(3) + ")";
      }
    }
  }

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g,
      c => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));
  }

  window.EditorCardInspector = {
    show: showCardPanel,
    clear() {
      const p = document.getElementById("chrx-card-panel");
      if (p) p.remove();
    },
  };

  document.addEventListener("editor:focusCard", function(e) {
    const detail = e.detail;
    if (!detail || !detail.cardId) return;
    
    const cardEl = document.querySelector(`.chrx-vkarta[data-card-id="${detail.cardId}"]`);
    if (cardEl) {
      cardEl.scrollIntoView({ behavior: "smooth", block: "center", inline: "center" });
      
      const rowEl = cardEl.closest(".chrx-row");
      if (rowEl) {
        rowEl.style.backgroundColor = "var(--chrx-slate-100)";
        setTimeout(() => rowEl.style.backgroundColor = "", 2000);
      }
      
      const oldBoxShadow = cardEl.style.boxShadow;
      cardEl.style.boxShadow = "0 0 0 4px var(--chrx-red)";
      setTimeout(() => cardEl.style.boxShadow = oldBoxShadow, 2000);
      
      const lessonId = cardEl.dataset.lessonId;
      if (lessonId && typeof showCardPanel === "function") {
        showCardPanel(lessonId, { source: cardEl.closest('.chrx-pending-strip') ? "pending" : "grid" });
      }
    }
  });

  /** Shallow-copy snapshot of placed cards (baseline for post-drag cell diffs). */
  function snapshotCards() {
    const S = window.APP && window.APP.school;
    return S && Array.isArray(S.cards) ? S.cards.map(c => ({ ...c })) : [];
  }

  /**
   * Incremental repaint after a drag commit: regenerate just the affected
   * (row, day) day-blocks from live data via the same dayBodyHtml generator
   * the full render uses — replacing the ~1000-node innerHTML rebuild (plus
   * scroll save/restore and label autofit reflows) with typically 1–2 small
   * group updates. Returns true only when every cell was patched; any
   * anomaly (missing row/group, out-of-range day) → false so the caller can
   * fall back to a full render. Skips structural passes (row-label autofit)
   * but keeps card-dependent syncs (pending count, class panel, subject
   * code fitting) and never touches scroll — nothing is torn down.
   */
  function patchCells(rootEl, cells) {
    const S = window.APP && window.APP.school;
    if (!S || !rootEl || !cells || !cells.length) return false;
    ensureEditorState();
    const perspective = window.APP.editor.perspective;
    const periods = displayPeriods(S);
    const visiblePeriodSet = new Set(periods.map(p => p.index | 0));
    const cardLookup = buildCardLookup(S, perspective, visiblePeriodSet);
    const numDays = dayCount(S);
    const rowsByKey = new Map();
    const allRows = rowsFor(S, perspective);
    for (const r of allRows) rowsByKey.set(r.key, r);

    if (window.APP.editor.viewMode === "focus") {
      const focusRow = resolveFocusRow(allRows, perspective);
      if (!focusRow) return false;
      if (!cells.some(cell => cell.rowKey === focusRow.key)) return true;
      const board = rootEl.querySelector(".chrx-focus-board");
      if (!board) return false;
      const isMobile = isMobileViewport(rootEl);
      board.style.setProperty("--chrx-days", isMobile ? "1" : String(numDays));
      const mobileDay = Math.max(0, Math.min(numDays - 1, (window.APP && window.APP.day) || 0));
      board.innerHTML = focusBoardInnerHtml(S, focusRow, periods, cardLookup, mobileDay, isMobile);
      syncUnplacedCount(S);
      updateClassPanel(S);
      autoFitSubjectCodes(rootEl, board);
      initRovingTabindex(rootEl);
      return true;
    }
    const escSel = (window.CSS && typeof CSS.escape === "function")
      ? CSS.escape : (s => String(s).replace(/"/g, "\\\""));
    const changedGroups = [];
    for (const cell of cells) {
      const row = rowsByKey.get(cell.rowKey);
      const day = cell.day | 0;
      if (!row || day < 0 || day >= numDays) return false;
      const rowEl = rootEl.querySelector(`.chrx-row[data-row="${escSel(cell.rowKey)}"]`);
      const groupEl = rowEl && rowEl.querySelector(`.chrx-day-body-group[data-day="${day}"]`);
      if (!groupEl) return false;
      const bellPeriodSet = bellSetFor(S, row, perspective);
      groupEl.innerHTML = dayBodyHtml(S, row, periods, day, cardLookup[cell.rowKey] || null, bellPeriodSet);
      changedGroups.push(groupEl);
    }
    syncUnplacedCount(S);
    updateClassPanel(S);
    for (const groupEl of changedGroups) autoFitSubjectCodes(rootEl, groupEl);
    initRovingTabindex(rootEl);
    return true;
  }

  return { render, setPerspective, patchCells, snapshotCards, cancelPendingCardClick };
})();

// [vite-esm] exports auto-generated by the 2026-07 Vite migration.
export const Editor = window.Editor;
export const EditorCardInspector = window.EditorCardInspector;
